+package com.itz.inventarios.config;
+
+import com.fasterxml.jackson.databind.ObjectMapper;
+import jakarta.servlet.http.HttpServletRequest;
+import jakarta.servlet.http.HttpServletResponse;
+import java.io.IOException;
+import java.nio.charset.StandardCharsets;
+import java.util.LinkedHashMap;
+import java.util.Map;
+import org.springframework.http.MediaType;
+import org.springframework.http.ProblemDetail;
+
+/** Escribe un ProblemDetail directamente en la respuesta servlet (fuera de MVC, como en los filtros de seguridad). */
+final class ProblemResponseWriter {
+
+    private ProblemResponseWriter() {
+    }
+
+    static void write(ObjectMapper objectMapper, HttpServletRequest request, HttpServletResponse response,
+            ProblemDetail pd) throws IOException {
+        Map<String, Object> body = new LinkedHashMap<>();
+        body.put("type", pd.getType().toString());
+        body.put("title", pd.getTitle());
+        body.put("status", pd.getStatus());
+        body.put("detail", pd.getDetail());
+        body.put("instance", request.getRequestURI());
+        response.setStatus(pd.getStatus());
+        response.setContentType(MediaType.APPLICATION_PROBLEM_JSON_VALUE);
+        response.setCharacterEncoding(StandardCharsets.UTF_8.name());
+        objectMapper.writeValue(response.getOutputStream(), body);
+    }
+}
