@@ -0,0 +1,63 @@
+package com.itz.inventarios.config;
+
+import static org.assertj.core.api.Assertions.assertThat;
+
+import com.fasterxml.jackson.databind.JsonNode;
+import com.fasterxml.jackson.databind.ObjectMapper;
+import org.junit.jupiter.api.Test;
+import org.springframework.http.HttpHeaders;
+import org.springframework.http.MediaType;
+import org.springframework.mock.web.MockHttpServletRequest;
+import org.springframework.mock.web.MockHttpServletResponse;
+import org.springframework.security.access.AccessDeniedException;
+import org.springframework.security.authentication.BadCredentialsException;
+
+class SecurityProblemHandlersTest {
+
+    private final ObjectMapper objectMapper = new ObjectMapper();
+
+    @Test
+    void entryPointResponde401ConProblemDetail() throws Exception {
+        MockHttpServletRequest request = new MockHttpServletRequest("GET", "/api/v1/users/me");
+        MockHttpServletResponse response = new MockHttpServletResponse();
+
+        new ProblemDetailAuthenticationEntryPoint(objectMapper)
+                .commence(request, response, new BadCredentialsException("x"));
+
+        assertThat(response.getStatus()).isEqualTo(401);
+        assertThat(response.getContentType()).startsWith(MediaType.APPLICATION_PROBLEM_JSON_VALUE);
+        assertThat(response.getHeader(HttpHeaders.WWW_AUTHENTICATE)).isEqualTo("Bearer");
+        JsonNode body = objectMapper.readTree(response.getContentAsString());
+        assertThat(body.get("status").asInt()).isEqualTo(401);
+        assertThat(body.get("title").asText()).isEqualTo("Unauthorized");
+        assertThat(body.get("detail").asText()).isEqualTo("Autenticación requerida o inválida.");
+        assertThat(body.get("instance").asText()).isEqualTo("/api/v1/users/me");
+    }
+
+    @Test
+    void accessDeniedHandlerResponde403ConProblemDetail() throws Exception {
+        MockHttpServletRequest request = new MockHttpServletRequest("DELETE", "/api/v1/algo");
+        MockHttpServletResponse response = new MockHttpServletResponse();
+
+        new ProblemDetailAccessDeniedHandler(objectMapper)
+                .handle(request, response, new AccessDeniedException("x"));
+
+        assertThat(response.getStatus()).isEqualTo(403);
+        assertThat(response.getContentType()).startsWith(MediaType.APPLICATION_PROBLEM_JSON_VALUE);
+        JsonNode body = objectMapper.readTree(response.getContentAsString());
+        assertThat(body.get("status").asInt()).isEqualTo(403);
+        assertThat(body.get("title").asText()).isEqualTo("Forbidden");
+        assertThat(body.get("detail").asText()).isEqualTo("No tiene permiso para realizar esta operación.");
+        assertThat(body.get("instance").asText()).isEqualTo("/api/v1/algo");
+    }
+
+    @Test
+    void noFiltraElMensajeDeLaExcepcion() throws Exception {
+        MockHttpServletResponse response = new MockHttpServletResponse();
+
+        new ProblemDetailAuthenticationEntryPoint(objectMapper)
+                .commence(new MockHttpServletRequest("GET", "/x"), response, new BadCredentialsException("secreto-interno"));
+
+        assertThat(response.getContentAsString()).doesNotContain("secreto-interno");
+    }
+}
