+package com.itz.inventarios.config;
+
+import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user;
+import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
+import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
+import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
+import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
+import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
+import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
+import org.springframework.context.annotation.Import;
+import org.springframework.http.MediaType;
+import org.springframework.security.access.prepost.PreAuthorize;
+import org.springframework.test.context.ActiveProfiles;
+import org.springframework.test.web.servlet.MockMvc;
+import org.springframework.web.bind.annotation.GetMapping;
+import org.springframework.web.bind.annotation.PostMapping;
+import org.springframework.web.bind.annotation.RestController;
+
+/** Slice de seguridad: rutas públicas, rutas protegidas, 401/403 en ProblemDetail y @PreAuthorize. */
+@WebMvcTest(controllers = SecurityWebSliceTest.ProbeController.class)
+@Import({SecurityConfig.class, ProblemDetailAuthenticationEntryPoint.class,
+        ProblemDetailAccessDeniedHandler.class, SecurityWebSliceTest.ProbeController.class})
+@ActiveProfiles("test")
+class SecurityWebSliceTest {
+
+    @RestController
+    static class ProbeController {
+        @GetMapping("/api/v1/probe/protected")
+        String protegida() {
+            return "ok";
+        }
+
+        @GetMapping("/api/v1/probe/admin")
+        @PreAuthorize("hasRole('ADMIN')")
+        String soloAdmin() {
+            return "admin";
+        }
+
+        @PostMapping("/api/v1/auth/probe")
+        String publica() {
+            return "public";
+        }
+    }
+
+    @Autowired
+    private MockMvc mockMvc;
+
+    @Test
+    void rutaProtegidaSinTokenResponde401ConProblemDetail() throws Exception {
+        mockMvc.perform(get("/api/v1/probe/protected"))
+                .andExpect(status().isUnauthorized())
+                .andExpect(header().string("WWW-Authenticate", "Bearer"))
+                .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON))
+                .andExpect(jsonPath("$.status").value(401))
+                .andExpect(jsonPath("$.title").value("Unauthorized"));
+    }
+
+    @Test
+    void rutaProtegidaAutenticadaResponde200() throws Exception {
+        mockMvc.perform(get("/api/v1/probe/protected").with(user("ana").roles("USER")))
+                .andExpect(status().isOk());
+    }
+
+    @Test
+    void rutasDeAuthSonPublicasYNoRequierenCsrf() throws Exception {
+        mockMvc.perform(post("/api/v1/auth/probe"))
+                .andExpect(status().isOk())
+                .andExpect(content().string("public"));
+    }
+
+    @Test
+    void preAuthorizeSinRolResponde403ConProblemDetail() throws Exception {
+        mockMvc.perform(get("/api/v1/probe/admin").with(user("ana").roles("USER")))
+                .andExpect(status().isForbidden())
+                .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON))
+                .andExpect(jsonPath("$.status").value(403))
+                .andExpect(jsonPath("$.title").value("Forbidden"));
+    }
+
+    @Test
+    void preAuthorizeConRolPermiteElAcceso() throws Exception {
+        mockMvc.perform(get("/api/v1/probe/admin").with(user("root").roles("ADMIN")))
+                .andExpect(status().isOk());
+    }
+}

