+import { Route } from '@angular/router';
+
+import { routes } from './app.routes';
+
+function findRoute(path: string): Route {
+  const route = routes.find((r) => r.path === path);
+  if (!route) {
+    throw new Error(`Ruta no encontrada: ${path}`);
+  }
+  return route;
+}
+
+describe('app.routes', () => {
+  it('redirige la raíz a home', () => {
+    const root = findRoute('');
+    expect(root.redirectTo).toBe('home');
+    expect(root.pathMatch).toBe('full');
+  });
+
+  it('define auth y home con lazy loading', async () => {
+    for (const path of ['auth', 'home']) {
+      const route = findRoute(path);
+      expect(typeof route.loadChildren).toBe('function');
+      const children = await (route.loadChildren as () => Promise<Route[]>)();
+      expect(Array.isArray(children)).toBe(true);
+    }
+  });
+
+  it('redirige rutas desconocidas a home', () => {
+    const wildcard = findRoute('**');
+    expect(wildcard.redirectTo).toBe('home');
+  });
+});
