+import { DOCUMENT } from '@angular/common';
+import { InjectionToken, inject } from '@angular/core';
+
+import { environment } from '../../../environments/environment';
+
+/** Configuración inyectada en runtime (p. ej. por nginx en /config.js). */
+export interface AppRuntimeConfig {
+  API_BASE_URL?: string;
+}
+
+type WindowWithConfig = Window & { __APP_CONFIG__?: AppRuntimeConfig };
+
+/**
+ * Resuelve la URL base de la API: valor de runtime si existe, si no el del environment.
+ * Elimina las barras finales; una cadena vacía significa "mismo origen".
+ */
+export function resolveApiBaseUrl(runtime: AppRuntimeConfig | undefined, fallback: string): string {
+  const candidate = runtime?.API_BASE_URL?.trim();
+  const value = candidate ? candidate : fallback;
+  return value.replace(/\/+$/, '');
+}
+
+/** URL base del backend (API_BASE_URL). */
+export const API_BASE_URL = new InjectionToken<string>('API_BASE_URL', {
+  providedIn: 'root',
+  factory: () => {
+    const win = inject(DOCUMENT).defaultView as WindowWithConfig | null;
+    return resolveApiBaseUrl(win?.__APP_CONFIG__, environment.apiBaseUrl);
+  },
+});
