+import { Injectable, inject } from '@angular/core';
+
+import { API_BASE_URL } from './api-base-url';
+
+/** Punto único de acceso a la configuración de la API. */
+@Injectable({ providedIn: 'root' })
+export class ApiConfigService {
+  readonly apiBaseUrl: string = inject(API_BASE_URL);
+
+  /** Construye la URL absoluta de un endpoint (con o sin barra inicial). */
+  url(path: string): string {
+    const normalized = path.startsWith('/') ? path : `/${path}`;
+    return `${this.apiBaseUrl}${normalized}`;
+  }
+
+  /** Indica si la URL pertenece al backend configurado. */
+  isApiUrl(url: string): boolean {
+    return this.apiBaseUrl !== '' ? url.startsWith(this.apiBaseUrl) : url.startsWith('/');
+  }
+}
