+import { HttpClient, provideHttpClient, withInterceptors } from '@angular/common/http';
+import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
+import { TestBed } from '@angular/core/testing';
+
+import { API_BASE_URL } from '../config/api-base-url';
+import { baseInterceptor } from './base.interceptor';
+
+describe('baseInterceptor', () => {
+  let http: HttpClient;
+  let controller: HttpTestingController;
+
+  beforeEach(() => {
+    TestBed.configureTestingModule({
+      providers: [
+        { provide: API_BASE_URL, useValue: 'http://api.test' },
+        provideHttpClient(withInterceptors([baseInterceptor])),
+        provideHttpClientTesting(),
+      ],
+    });
+    http = TestBed.inject(HttpClient);
+    controller = TestBed.inject(HttpTestingController);
+  });
+
+  afterEach(() => controller.verify());
+
+  it('añade Accept: application/json a las peticiones a la API', () => {
+    http.get('http://api.test/api/v1/users/me').subscribe();
+    const req = controller.expectOne('http://api.test/api/v1/users/me');
+    expect(req.request.headers.get('Accept')).toBe('application/json');
+    req.flush({});
+  });
+
+  it('respeta un Accept ya definido', () => {
+    http
+      .get('http://api.test/x', { headers: { Accept: 'text/plain' } })
+      .subscribe();
+    const req = controller.expectOne('http://api.test/x');
+    expect(req.request.headers.get('Accept')).toBe('text/plain');
+    req.flush('ok');
+  });
+
+  it('no modifica peticiones a otros orígenes', () => {
+    http.get('https://otro.example.com/data').subscribe();
+    const req = controller.expectOne('https://otro.example.com/data');
+    expect(req.request.headers.has('Accept')).toBe(false);
+    req.flush({});
+  });
+
