+import { HttpInterceptorFn } from '@angular/common/http';
+import { inject } from '@angular/core';
+
+import { ApiConfigService } from '../config/api-config.service';
+
+/**
+ * Interceptor base: solo normaliza cabeceras de las peticiones a la API.
+ * No contiene lógica de sesión (Bearer, 401) — eso llega con el módulo auth.
+ */
+export const baseInterceptor: HttpInterceptorFn = (req, next) => {
+  const apiConfig = inject(ApiConfigService);
+  if (apiConfig.isApiUrl(req.url) && !req.headers.has('Accept')) {
+    return next(req.clone({ setHeaders: { Accept: 'application/json' } }));
+  }
+  return next(req);
+};
