+package com.itz.inventarios.auth.domain;
+
+import jakarta.persistence.Column;
+import jakarta.persistence.Entity;
+import jakarta.persistence.EnumType;
+import jakarta.persistence.Enumerated;
+import jakarta.persistence.GeneratedValue;
+import jakarta.persistence.GenerationType;
+import jakarta.persistence.Id;
+import jakarta.persistence.Table;
+import java.time.Instant;
+import java.util.UUID;
+import lombok.Getter;
+import lombok.NoArgsConstructor;
+
+/** Registro de auditoría de autenticación. Nunca guarda contraseñas. */
+@Entity
+@Table(name = "auth_event")
+@Getter
+@NoArgsConstructor
+public class AuthEvent {
+
+    @Id
+    @GeneratedValue(strategy = GenerationType.IDENTITY)
+    private Long id;
+
+    @Column(name = "user_id")
+    private UUID userId;
+
+    @Column(name = "email_intentado")
+    private String emailIntentado;
+
+    @Enumerated(EnumType.STRING)
+    @Column(nullable = false, length = 20)
+    private AuthEventType tipo;
+
+    @Column(length = 45)
+    private String ip;
+
+    @Column(name = "created_at", nullable = false, updatable = false)
+    private Instant createdAt;
+
+    public AuthEvent(AuthEventType tipo, UUID userId, String emailIntentado, String ip, Instant createdAt) {
+        this.tipo = tipo;
+        this.userId = userId;
+        this.emailIntentado = emailIntentado;
+        this.ip = ip;
+        this.createdAt = createdAt;
+    }
+
+    @Override
+    public String toString() {
+        return "AuthEvent[tipo=" + tipo + ", userId=" + userId + ", email=" + emailIntentado + ", ip=" + ip
+                + ", createdAt=" + createdAt + "]";
+    }
+}
