+package com.itz.inventarios.auth.service;
+
+import com.itz.inventarios.auth.domain.AuthEvent;
+import com.itz.inventarios.auth.domain.AuthEventType;
+import com.itz.inventarios.auth.repository.AuthEventRepository;
+import java.time.Clock;
+import java.util.UUID;
+import org.springframework.stereotype.Service;
+import org.springframework.transaction.annotation.Transactional;
+
+/** Auditoría de autenticación. Recibe solo correo, tipo e IP: nunca la contraseña. */
+@Service
+public class AuthEventService {
+
+    private static final int MAX_EMAIL_LENGTH = 255;
+    private static final int MAX_IP_LENGTH = 45;
+
+    private final AuthEventRepository authEventRepository;
+    private final Clock clock;
+
+    public AuthEventService(AuthEventRepository authEventRepository, Clock clock) {
+        this.authEventRepository = authEventRepository;
+        this.clock = clock;
+    }
+
+    @Transactional
+    public void record(AuthEventType type, UUID userId, String emailAttempted, String ip) {
+        authEventRepository.save(new AuthEvent(type, userId, truncate(emailAttempted, MAX_EMAIL_LENGTH),
+                truncate(ip, MAX_IP_LENGTH), clock.instant()));
+    }
+
+    private static String truncate(String value, int max) {
+        if (value == null || value.length() <= max) {
+            return value;
+        }
+        return value.substring(0, max);
+    }
+}
