@@ -0,0 +1,79 @@
+package com.itz.inventarios.auth.service;
+
+import com.itz.inventarios.auth.domain.AuthEventType;
+import com.itz.inventarios.common.exception.ApiException;
+import com.itz.inventarios.common.exception.TooManyAttemptsException;
+import com.itz.inventarios.user.domain.User;
+import com.itz.inventarios.user.repository.UserRepository;
+import java.time.Clock;
+import java.time.Duration;
+import java.util.Locale;
+import java.util.Optional;
+import org.springframework.http.HttpStatus;
+import org.springframework.security.crypto.password.PasswordEncoder;
+import org.springframework.stereotype.Service;
+
+/**
+ * Caso de uso de inicio de sesión. Deliberadamente sin transacción global: los eventos de auditoría de
+ * un intento fallido deben persistir aunque se lance la excepción 401.
+ */
+@Service
+public class AuthService {
+
+    public static final String INVALID_CREDENTIALS_MESSAGE = "Correo o contraseña incorrectos.";
+
+    private final UserRepository userRepository;
+    private final PasswordEncoder passwordEncoder;
+    private final JwtService jwtService;
+    private final LoginAttemptService loginAttempts;
+    private final AuthEventService authEvents;
+    private final Clock clock;
+    /** Hash señuelo para gastar el mismo tiempo de BCrypt cuando el correo no existe. */
+    private final String decoyHash;
+
+    public AuthService(UserRepository userRepository, PasswordEncoder passwordEncoder, JwtService jwtService,
+            LoginAttemptService loginAttempts, AuthEventService authEvents, Clock clock) {
+        this.userRepository = userRepository;
+        this.passwordEncoder = passwordEncoder;
+        this.jwtService = jwtService;
+        this.loginAttempts = loginAttempts;
+        this.authEvents = authEvents;
+        this.clock = clock;
+        this.decoyHash = passwordEncoder.encode("decoy-password-not-used");
+    }
+
+    public LoginResult login(String rawEmail, String rawPassword, String ip) {
+        String email = normalizeEmail(rawEmail);
+
+        Duration lock = loginAttempts.remainingLock(email);
+        if (!lock.isZero()) {
+            authEvents.record(AuthEventType.LOGIN_FAIL, null, email, ip);
+            throw new TooManyAttemptsException((lock.toMillis() + 999) / 1000);
+        }
+
+        Optional<User> found = userRepository.findByEmail(email);
+        boolean valid = found.isPresent() && found.get().isEnabled()
+                && passwordEncoder.matches(rawPassword, found.get().getPasswordHash());
+        if (found.isEmpty()) {
+            passwordEncoder.matches(rawPassword, decoyHash);
+        }
+
+        if (!valid) {
+            loginAttempts.recordFailure(email);
+            authEvents.record(AuthEventType.LOGIN_FAIL, found.map(User::getId).orElse(null), email, ip);
+            throw new ApiException(HttpStatus.UNAUTHORIZED, INVALID_CREDENTIALS_MESSAGE);
+        }
+
+        User user = found.get();
+        loginAttempts.recordSuccess(email);
+        user.setLastLoginAt(clock.instant());
+        userRepository.save(user);
+        IssuedToken token = jwtService.issue(user);
+        authEvents.record(AuthEventType.LOGIN_OK, user.getId(), email, ip);
+        return new LoginResult(token, user);
+    }
+
+    private static String normalizeEmail(String rawEmail) {
+        return rawEmail == null ? "" : rawEmail.trim().toLowerCase(Locale.ROOT);
+    }
+}
