@@ -0,0 +1,61 @@
+package com.itz.inventarios.auth.service;
+
+import com.itz.inventarios.auth.domain.AuthenticatedUser;
+import com.itz.inventarios.auth.repository.RevokedTokenRepository;
+import jakarta.servlet.FilterChain;
+import jakarta.servlet.ServletException;
+import jakarta.servlet.http.HttpServletRequest;
+import jakarta.servlet.http.HttpServletResponse;
+import java.io.IOException;
+import java.util.List;
+import org.springframework.http.HttpHeaders;
+import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
+import org.springframework.security.core.GrantedAuthority;
+import org.springframework.security.core.authority.SimpleGrantedAuthority;
+import org.springframework.security.core.context.SecurityContextHolder;
+import org.springframework.web.filter.OncePerRequestFilter;
+
+/**
+ * Valida el Bearer JWT (firma, expiración y jti no revocado). Si es válido autentica la petición con los
+ * roles del token; si no, la deja anónima y el entry point responde 401 en las rutas protegidas.
+ * No es un bean: lo registra {@code SecurityConfig} solo dentro de la cadena de seguridad.
+ */
+public class JwtAuthenticationFilter extends OncePerRequestFilter {
+
+    private static final String BEARER_PREFIX = "Bearer ";
+
+    private final JwtService jwtService;
+    private final RevokedTokenRepository revokedTokenRepository;
+
+    public JwtAuthenticationFilter(JwtService jwtService, RevokedTokenRepository revokedTokenRepository) {
+        this.jwtService = jwtService;
+        this.revokedTokenRepository = revokedTokenRepository;
+    }
+
+    @Override
+    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
+            throws ServletException, IOException {
+        String header = request.getHeader(HttpHeaders.AUTHORIZATION);
+        if (header != null && header.regionMatches(true, 0, BEARER_PREFIX, 0, BEARER_PREFIX.length())) {
+            authenticate(header.substring(BEARER_PREFIX.length()).trim());
+        }
+        chain.doFilter(request, response);
+    }
+
+    private void authenticate(String token) {
+        try {
+            TokenClaims claims = jwtService.parse(token);
+            if (revokedTokenRepository.existsById(claims.jti())) {
+                return;
+            }
+            List<GrantedAuthority> authorities = claims.roles().stream()
+                    .<GrantedAuthority>map(role -> new SimpleGrantedAuthority("ROLE_" + role))
+                    .toList();
+            UsernamePasswordAuthenticationToken authentication = new UsernamePasswordAuthenticationToken(
+                    new AuthenticatedUser(claims.userId(), claims.email()), null, authorities);
+            SecurityContextHolder.getContext().setAuthentication(authentication);
+        } catch (InvalidTokenException e) {
+            SecurityContextHolder.clearContext();
+        }
+    }
+}
