@@ -0,0 +1,79 @@
+package com.itz.inventarios.auth.service;
+
+import com.itz.inventarios.config.JwtProperties;
+import com.itz.inventarios.user.domain.Role;
+import com.itz.inventarios.user.domain.User;
+import io.jsonwebtoken.Claims;
+import io.jsonwebtoken.Jws;
+import io.jsonwebtoken.JwtException;
+import io.jsonwebtoken.Jwts;
+import io.jsonwebtoken.security.Keys;
+import java.nio.charset.StandardCharsets;
+import java.time.Clock;
+import java.time.Duration;
+import java.time.Instant;
+import java.util.Date;
+import java.util.List;
+import java.util.UUID;
+import javax.crypto.SecretKey;
+import org.springframework.stereotype.Service;
+
+/** Emisión y validación de JWT HS256 de vida corta, cada uno con un jti único para poder revocarlo. */
+@Service
+public class JwtService {
+
+    private static final String ALGORITHM = "HS256";
+    private static final String CLAIM_EMAIL = "email";
+    private static final String CLAIM_ROLES = "roles";
+
+    private final SecretKey key;
+    private final Duration accessTtl;
+    private final Clock clock;
+
+    public JwtService(JwtProperties properties, Clock clock) {
+        this.key = Keys.hmacShaKeyFor(properties.secret().getBytes(StandardCharsets.UTF_8));
+        this.accessTtl = Duration.ofMinutes(properties.accessTtlMinutes());
+        this.clock = clock;
+    }
+
+    public IssuedToken issue(User user) {
+        Instant now = clock.instant();
+        Instant expiresAt = now.plus(accessTtl);
+        String jti = UUID.randomUUID().toString();
+        List<String> roles = user.getRoles().stream().map(Role::getName).sorted().toList();
+        String token = Jwts.builder()
+                .id(jti)
+                .subject(user.getId().toString())
+                .claim(CLAIM_EMAIL, user.getEmail())
+                .claim(CLAIM_ROLES, roles)
+                .issuedAt(Date.from(now))
+                .expiration(Date.from(expiresAt))
+                .signWith(key, Jwts.SIG.HS256)
+                .compact();
+        return new IssuedToken(token, jti, expiresAt);
+    }
+
+    /** @throws InvalidTokenException si el token no es válido o ya expiró */
+    public TokenClaims parse(String token) {
+        try {
+            Jws<Claims> jws = Jwts.parser()
+                    .verifyWith(key)
+                    .clock(() -> Date.from(clock.instant()))
+                    .build()
+                    .parseSignedClaims(token);
+            if (!ALGORITHM.equals(jws.getHeader().getAlgorithm())) {
+                throw new InvalidTokenException("Algoritmo de firma no permitido", null);
+            }
+            Claims claims = jws.getPayload();
+            if (claims.getId() == null || claims.getSubject() == null || claims.getExpiration() == null) {
+                throw new InvalidTokenException("Token incompleto", null);
+            }
+            List<?> rawRoles = claims.get(CLAIM_ROLES, List.class);
+            List<String> roles = rawRoles == null ? List.of() : rawRoles.stream().map(String::valueOf).toList();
+            return new TokenClaims(claims.getId(), UUID.fromString(claims.getSubject()),
+                    claims.get(CLAIM_EMAIL, String.class), roles, claims.getExpiration().toInstant());
+        } catch (JwtException | IllegalArgumentException e) {
+            throw new InvalidTokenException("Token inválido", e);
+        }
+    }
+}
