@@ -0,0 +1,69 @@
+package com.itz.inventarios.auth.service;
+
+import java.time.Clock;
+import java.time.Duration;
+import java.time.Instant;
+import java.util.concurrent.ConcurrentHashMap;
+import java.util.concurrent.ConcurrentMap;
+import org.springframework.beans.factory.annotation.Value;
+import org.springframework.stereotype.Service;
+
+/**
+ * Protección contra fuerza bruta en memoria: tras {@code maxAttempts} fallos consecutivos de una misma clave
+ * (el correo normalizado, exista o no) la clave queda bloqueada durante {@code lockMinutes}. Los fallos
+ * antiguos, fuera de esa misma ventana, no se acumulan.
+ */
+@Service
+public class LoginAttemptService {
+
+    private static final int PRUNE_THRESHOLD = 10_000;
+
+    private record Attempt(int failures, Instant lastFailureAt, Instant lockedUntil) {
+    }
+
+    private final ConcurrentMap<String, Attempt> attempts = new ConcurrentHashMap<>();
+    private final Clock clock;
+    private final int maxAttempts;
+    private final Duration lockDuration;
+
+    public LoginAttemptService(Clock clock,
+            @Value("${app.security.login-max-attempts:5}") int maxAttempts,
+            @Value("${app.security.login-lock-minutes:15}") int lockMinutes) {
+        this.clock = clock;
+        this.maxAttempts = maxAttempts;
+        this.lockDuration = Duration.ofMinutes(lockMinutes);
+    }
+
+    /** Tiempo de bloqueo restante para la clave, o {@link Duration#ZERO} si no está bloqueada. */
+    public Duration remainingLock(String key) {
+        Attempt attempt = attempts.get(key);
+        Instant now = clock.instant();
+        if (attempt == null || attempt.lockedUntil() == null || !attempt.lockedUntil().isAfter(now)) {
+            return Duration.ZERO;
+        }
+        return Duration.between(now, attempt.lockedUntil());
+    }
+
+    public void recordFailure(String key) {
+        Instant now = clock.instant();
+        if (attempts.size() > PRUNE_THRESHOLD) {
+            attempts.values().removeIf(a -> isStale(a, now));
+        }
+        attempts.compute(key, (k, previous) -> {
+            int failures = (previous == null || isStale(previous, now)) ? 1 : previous.failures() + 1;
+            Instant lockedUntil = failures >= maxAttempts ? now.plus(lockDuration) : null;
+            return new Attempt(failures, now, lockedUntil);
+        });
+    }
+
+    public void recordSuccess(String key) {
+        attempts.remove(key);
+    }
+
+    private boolean isStale(Attempt attempt, Instant now) {
+        if (attempt.lockedUntil() != null) {
+            return !attempt.lockedUntil().isAfter(now);
+        }
+        return attempt.lastFailureAt().plus(lockDuration).isBefore(now);
+    }
+}
