+package com.itz.inventarios.auth.web;
+
+import com.itz.inventarios.auth.service.AuthService;
+import com.itz.inventarios.auth.service.LoginResult;
+import com.itz.inventarios.user.mapper.UserMapper;
+import io.swagger.v3.oas.annotations.Operation;
+import io.swagger.v3.oas.annotations.media.Content;
+import io.swagger.v3.oas.annotations.media.Schema;
+import io.swagger.v3.oas.annotations.responses.ApiResponse;
+import io.swagger.v3.oas.annotations.security.SecurityRequirements;
+import io.swagger.v3.oas.annotations.tags.Tag;
+import jakarta.servlet.http.HttpServletRequest;
+import jakarta.validation.Valid;
+import org.springframework.http.ProblemDetail;
+import org.springframework.web.bind.annotation.PostMapping;
+import org.springframework.web.bind.annotation.RequestBody;
+import org.springframework.web.bind.annotation.RequestMapping;
+import org.springframework.web.bind.annotation.RestController;
+
+@RestController
+@RequestMapping("/api/v1/auth")
+@Tag(name = "Autenticación", description = "Inicio de sesión con correo y contraseña")
+public class AuthController {
+
+    private static final String PROBLEM_JSON = "application/problem+json";
+
+    private final AuthService authService;
+    private final UserMapper userMapper;
+
+    public AuthController(AuthService authService, UserMapper userMapper) {
+        this.authService = authService;
+        this.userMapper = userMapper;
+    }
+
+    @PostMapping("/login")
+    @SecurityRequirements
+    @Operation(summary = "Iniciar sesión",
+            description = "Autentica con correo y contraseña y devuelve un JWT de vida corta. "
+                    + "El correo se compara sin distinguir mayúsculas y sin espacios en los extremos. "
+                    + "El error de credenciales es genérico y no revela si el correo existe.")
+    @ApiResponse(responseCode = "200", description = "Autenticación correcta")
+    @ApiResponse(responseCode = "400", description = "Correo o contraseña vacíos o correo con formato inválido",
+            content = @Content(mediaType = PROBLEM_JSON, schema = @Schema(implementation = ProblemDetail.class)))
+    @ApiResponse(responseCode = "401", description = "Correo o contraseña incorrectos (mensaje genérico)",
+            content = @Content(mediaType = PROBLEM_JSON, schema = @Schema(implementation = ProblemDetail.class)))
+    @ApiResponse(responseCode = "429",
+            description = "Demasiados intentos fallidos: bloqueo temporal (cabecera Retry-After en segundos)",
+            content = @Content(mediaType = PROBLEM_JSON, schema = @Schema(implementation = ProblemDetail.class)))
+    public LoginResponse login(@Valid @RequestBody LoginRequest request, HttpServletRequest http) {
+        LoginResult result = authService.login(request.email(), request.password(), http.getRemoteAddr());
+        return new LoginResponse(result.token().token(), "Bearer", result.token().expiresAt(),
+                userMapper.toResponse(result.user()));
+    }
+}
