@@ -0,0 +1,40 @@
+package com.itz.inventarios.user.service;
+
+import com.itz.inventarios.user.domain.User;
+import com.itz.inventarios.user.repository.UserRepository;
+import org.springframework.beans.factory.annotation.Value;
+import org.springframework.boot.ApplicationArguments;
+import org.springframework.boot.ApplicationRunner;
+import org.springframework.security.crypto.password.PasswordEncoder;
+import org.springframework.stereotype.Component;
+
+/**
+ * Solo para desarrollo: si {@code SEED_PASSWORD} está definida, asigna esa contraseña (con BCrypt) a las
+ * cuentas sembradas por Flyway que aún tienen el hash sin definir. Sin la variable no hace nada, así que en
+ * producción las cuentas sembradas siguen sin poder iniciar sesión.
+ */
+@Component
+public class SeedUserPasswordInitializer implements ApplicationRunner {
+
+    private final UserRepository userRepository;
+    private final PasswordEncoder passwordEncoder;
+    private final String seedPassword;
+
+    public SeedUserPasswordInitializer(UserRepository userRepository, PasswordEncoder passwordEncoder,
+            @Value("${app.seed.password:}") String seedPassword) {
+        this.userRepository = userRepository;
+        this.passwordEncoder = passwordEncoder;
+        this.seedPassword = seedPassword;
+    }
+
+    @Override
+    public void run(ApplicationArguments args) {
+        if (seedPassword == null || seedPassword.isBlank()) {
+            return;
+        }
+        for (User user : userRepository.findByPasswordHash(User.UNSET_PASSWORD_HASH)) {
+            user.setPasswordHash(passwordEncoder.encode(seedPassword));
+            userRepository.save(user);
+        }
+    }
+}
