+
+describe('authInterceptor', () => {
+  let http: HttpClient;
+  let controller: HttpTestingController;
+  let tokens: TokenStorage;
+  let navigate: jest.SpyInstance;
+
+  beforeEach(() => {
+    sessionStorage.clear();
+    TestBed.configureTestingModule({
+      providers: [
+        provideRouter([]),
+        provideHttpClient(withInterceptors([authInterceptor])),
+        provideHttpClientTesting(),
+        { provide: API_BASE_URL, useValue: 'http://api' },
+      ],
+    });
+    http = TestBed.inject(HttpClient);
+    controller = TestBed.inject(HttpTestingController);
+    tokens = TestBed.inject(TokenStorage);
+    navigate = jest.spyOn(TestBed.inject(Router), 'navigateByUrl').mockResolvedValue(true);
+  });
+
+  afterEach(() => controller.verify());
+
+  it('añade la cabecera Bearer a las peticiones a la API', () => {
+    tokens.set('jwt');
+    http.get('http://api/api/v1/users/me').subscribe();
+    const req = controller.expectOne('http://api/api/v1/users/me');
+    expect(req.request.headers.get('Authorization')).toBe('Bearer jwt');
+    req.flush({});
+  });
+
+  it('no añade cabecera si no hay token', () => {
+    http.get('http://api/api/v1/users/me').subscribe();
+    const req = controller.expectOne('http://api/api/v1/users/me');
+    expect(req.request.headers.has('Authorization')).toBe(false);
+    req.flush({});
+  });
+
+  it('no envía el token a URLs externas', () => {
+    tokens.set('jwt');
+    http.get('http://otro.com/x').subscribe();
+    const req = controller.expectOne('http://otro.com/x');
+    expect(req.request.headers.has('Authorization')).toBe(false);
+    req.flush({});
+  });
+
+  it('ante 401 limpia la sesión y redirige a /login', () => {
+    tokens.set('jwt');
+    let status = 0;
+    http.get('http://api/api/v1/users/me').subscribe({ error: (e) => (status = e.status) });
+    controller
+      .expectOne('http://api/api/v1/users/me')
+      .flush({}, { status: 401, statusText: 'Unauthorized' });
+
+    expect(status).toBe(401);
+    expect(tokens.get()).toBeNull();
+    expect(navigate).toHaveBeenCalledWith('/login');
+  });
+
+  it('un 401 del login no limpia ni redirige (lo gestiona la pantalla)', () => {
+    tokens.set('jwt');
+    http.post('http://api/api/v1/auth/login', {}).subscribe({ error: () => undefined });
+    controller
+      .expectOne('http://api/api/v1/auth/login')
+      .flush({}, { status: 401, statusText: 'Unauthorized' });
+
+    expect(tokens.get()).toBe('jwt');
+    expect(navigate).not.toHaveBeenCalled();
+  });
+
+  it('otros errores no cierran la sesión', () => {
+    tokens.set('jwt');
+    http.get('http://api/api/v1/users/me').subscribe({ error: () => undefined });
