@@ -0,0 +1,34 @@
+import { HttpErrorResponse, HttpInterceptorFn } from '@angular/common/http';
+import { inject } from '@angular/core';
+import { Router } from '@angular/router';
+import { catchError, throwError } from 'rxjs';
+
+import { AuthService, LOGIN_PATH } from './auth.service';
+import { ApiConfigService } from './config/api-config.service';
+
+/**
+ * Añade el Bearer a las peticiones a la API. Ante un 401 (salvo el del propio login)
+ * limpia la sesión y redirige a /login.
+ */
+export const authInterceptor: HttpInterceptorFn = (req, next) => {
+  const api = inject(ApiConfigService);
+  if (!api.isApiUrl(req.url)) {
+    return next(req);
+  }
+
+  const auth = inject(AuthService);
+  const router = inject(Router);
+  const token = auth.token;
+  const request = token ? req.clone({ setHeaders: { Authorization: `Bearer ${token}` } }) : req;
+  const isLogin = req.url.endsWith(LOGIN_PATH);
+
+  return next(request).pipe(
+    catchError((error: unknown) => {
+      if (error instanceof HttpErrorResponse && error.status === 401 && !isLogin) {
+        auth.clearSession();
+        void router.navigateByUrl('/login');
+      }
+      return throwError(() => error);
+    }),
+  );
+};
