+import { HttpClient } from '@angular/common/http';
+import { Injectable, inject } from '@angular/core';
+import { BehaviorSubject, Observable, map, tap } from 'rxjs';
+
+import { ApiConfigService } from './config/api-config.service';
+import { TokenStorage } from './token.storage';
+
+/** Cuenta autenticada (GET /api/v1/users/me). */
+export interface UserProfile {
+  id: string;
+  email: string;
+  fullName: string;
+  roles: string[];
+  lastLoginAt: string | null;
+}
+
+/** Respuesta de POST /api/v1/auth/login. */
+export interface LoginResponse {
+  accessToken: string;
+  tokenType: string;
+  expiresAt: string;
+  user: UserProfile;
+}
+
+export const LOGIN_PATH = '/api/v1/auth/login';
+const ME_PATH = '/api/v1/users/me';
+
+/** Estado de sesión (BehaviorSubject) y llamadas de autenticación. */
+@Injectable({ providedIn: 'root' })
+export class AuthService {
+  private readonly http = inject(HttpClient);
+  private readonly api = inject(ApiConfigService);
+  private readonly tokens = inject(TokenStorage);
+  private readonly userSubject = new BehaviorSubject<UserProfile | null>(null);
+
+  readonly user$: Observable<UserProfile | null> = this.userSubject.asObservable();
+
+  get currentUser(): UserProfile | null {
+    return this.userSubject.value;
+  }
+
+  get token(): string | null {
+    return this.tokens.get();
+  }
+
+  isAuthenticated(): boolean {
+    return this.tokens.get() !== null;
+  }
+
+  login(email: string, password: string): Observable<UserProfile> {
+    return this.http.post<LoginResponse>(this.api.url(LOGIN_PATH), { email, password }).pipe(
+      tap((response) => {
+        this.tokens.set(response.accessToken);
+        this.userSubject.next(response.user);
+      }),
+      map((response) => response.user),
+    );
+  }
+
+  loadProfile(): Observable<UserProfile> {
+    return this.http
+      .get<UserProfile>(this.api.url(ME_PATH))
+      .pipe(tap((user) => this.userSubject.next(user)));
+  }
+
+  clearSession(): void {
+    this.tokens.clear();
+    this.userSubject.next(null);
+  }
+}
