@@ -0,0 +1,161 @@
+import { HttpErrorResponse } from '@angular/common/http';
+import { Component, inject } from '@angular/core';
+import {
+  AbstractControl,
+  NonNullableFormBuilder,
+  ReactiveFormsModule,
+  ValidationErrors,
+  Validators,
+} from '@angular/forms';
+import { Router } from '@angular/router';
+import { ButtonModule } from 'primeng/button';
+import { InputTextModule } from 'primeng/inputtext';
+
+import { AuthService } from '../../../core/auth.service';
+
+type LoginError = 'invalid' | 'rateLimited' | 'unavailable';
+
+const ERROR_MESSAGES: Record<LoginError, string> = {
+  invalid: 'Correo o contraseña incorrectos.',
+  rateLimited: 'Demasiados intentos. Espera unos minutos e inténtalo de nuevo.',
+  unavailable:
+    'El servicio no está disponible en este momento. Inténtalo de nuevo más tarde.',
+};
+
+const FIELD_MESSAGES: Record<string, Record<string, string>> = {
+  email: {
+    required: 'El correo es obligatorio.',
+    email: 'El correo no tiene un formato válido.',
+  },
+  password: {
+    required: 'La contraseña es obligatoria.',
+  },
+};
+
+/** Correo obligatorio y con formato válido, ignorando espacios en los extremos. */
+function trimmedEmail(control: AbstractControl): ValidationErrors | null {
+  const value = String(control.value ?? '').trim();
+  if (value === '') {
+    return { required: true };
+  }
+  return Validators.email({ value } as AbstractControl);
+}
+
+/** Pantalla de inicio de sesión con correo y contraseña. */
+@Component({
+  selector: 'app-login',
+  standalone: true,
+  imports: [ReactiveFormsModule, InputTextModule, ButtonModule],
+  template: `
+    <section class="mx-auto mt-10 w-full max-w-md rounded-lg bg-white p-6 shadow">
+      <h1 class="mb-6 text-2xl font-semibold text-slate-800">Iniciar sesión</h1>
+
+      @if (error) {
+        <div
+          data-testid="login-error"
+          role="alert"
+          class="mb-4 rounded border border-red-300 bg-red-50 p-3 text-sm text-red-700"
+        >
+          {{ errorMessage }}
+        </div>
+      }
+
+      <form [formGroup]="form" (ngSubmit)="onSubmit()" novalidate class="flex flex-col gap-4">
+        <div class="flex flex-col gap-1">
+          <label for="email" class="text-sm font-medium text-slate-700">Correo</label>
+          <input
+            id="email"
+            type="email"
+            pInputText
+            formControlName="email"
+            autocomplete="username"
+            class="w-full"
+          />
+          @if (fieldError('email'); as message) {
+            <small class="text-red-600" role="alert">{{ message }}</small>
+          }
+        </div>
+
+        <div class="flex flex-col gap-1">
+          <label for="password" class="text-sm font-medium text-slate-700">Contraseña</label>
+          <input
+            id="password"
+            type="password"
+            pInputText
+            formControlName="password"
+            autocomplete="current-password"
+            class="w-full"
+          />
+          @if (fieldError('password'); as message) {
+            <small class="text-red-600" role="alert">{{ message }}</small>
+          }
+        </div>
+
+        <button pButton type="submit" [disabled]="loading" class="w-full justify-center">
+          Iniciar sesión
+        </button>
+      </form>
+    </section>
+  `,
+})
+export class LoginComponent {
+  private readonly auth = inject(AuthService);
+  private readonly router = inject(Router);
+
+  readonly form = inject(NonNullableFormBuilder).group({
+    email: ['', [trimmedEmail]],
+    password: ['', [Validators.required]],
+  });
+
+  loading = false;
+  error: LoginError | null = null;
+
+  get errorMessage(): string {
+    return this.error ? ERROR_MESSAGES[this.error] : '';
+  }
+
+  fieldError(name: 'email' | 'password'): string | null {
+    const control = this.form.controls[name];
+    if (!control.touched || !control.errors) {
+      return null;
+    }
+    const key = Object.keys(control.errors)[0];
+    return FIELD_MESSAGES[name][key] ?? null;
+  }
+
+  onSubmit(): void {
+    if (this.loading) {
+      return;
+    }
+    this.error = null;
+    if (this.form.invalid) {
+      this.form.markAllAsTouched();
+      return;
+    }
+
+    const { email, password } = this.form.getRawValue();
+    this.loading = true;
+    this.auth.login(email.trim(), password).subscribe({
+      next: () => {
+        this.loading = false;
+        void this.router.navigateByUrl('/home');
+      },
+      error: (err: unknown) => {
+        this.loading = false;
+        this.error = this.classify(err);
+        this.form.controls.password.reset('');
+      },
+    });
+  }
+
+  private classify(err: unknown): LoginError {
+    const status = err instanceof HttpErrorResponse ? err.status : 0;
+    if (status === 429) {
+      return 'rateLimited';
+    }
+    if (status === 0 || status >= 500) {
+      return 'unavailable';
+    }
+    return 'invalid';
+  }
+}
