+import { AsyncPipe } from '@angular/common';
+import { Component, OnInit, inject } from '@angular/core';
+
+import { AuthService } from '../../core/auth.service';
+
+/** Pantalla protegida inicial: muestra los datos de la cuenta (/users/me). */
+@Component({
+  selector: 'app-home',
+  standalone: true,
+  imports: [AsyncPipe],
+  template: `
+    <section class="rounded-lg bg-white p-6 shadow">
+      <h1 class="mb-4 text-2xl font-semibold text-slate-800">Inicio</h1>
+
+      @if (loadFailed) {
+        <p data-testid="home-error" role="alert" class="text-red-700">
+          No se pudieron cargar los datos de tu cuenta. Inténtalo de nuevo más tarde.
+        </p>
+      }
+
+      @if (user$ | async; as user) {
+        <p class="mb-4 text-lg">
+          Bienvenido, <strong>{{ user.fullName }}</strong>
+        </p>
+        <dl class="grid grid-cols-1 gap-2 sm:grid-cols-2">
+          <div>
+            <dt class="text-sm text-slate-500">Correo</dt>
+            <dd>{{ user.email }}</dd>
+          </div>
+          <div>
+            <dt class="text-sm text-slate-500">Roles</dt>
+            <dd>{{ user.roles.join(', ') }}</dd>
+          </div>
+        </dl>
+      }
+    </section>
+  `,
+})
+export class HomeComponent implements OnInit {
+  private readonly auth = inject(AuthService);
+
+  readonly user$ = this.auth.user$;
+  loadFailed = false;
+
+  ngOnInit(): void {
+    if (this.auth.currentUser === null) {
+      this.auth.loadProfile().subscribe({ error: () => (this.loadFailed = true) });
+    }
+  }
+}
