+package com.itz.inventarios.common.ratelimit;
+
+import java.time.Clock;
+import java.time.Duration;
+import java.time.Instant;
+import java.util.ArrayDeque;
+import java.util.Deque;
+import java.util.concurrent.ConcurrentHashMap;
+import java.util.concurrent.ConcurrentMap;
+
+/**
+ * Limitador de frecuencia en memoria con ventana deslizante: cada clave admite {@code maxRequests}
+ * solicitudes en cualquier intervalo de {@code window}. Las solicitudes rechazadas no se contabilizan.
+ * El estado es local a la instancia.
+ */
+public class SlidingWindowRateLimiter {
+
+    private static final int PRUNE_THRESHOLD = 10_000;
+
+    private final ConcurrentMap<String, Deque<Instant>> hits = new ConcurrentHashMap<>();
+    private final Clock clock;
+    private final int maxRequests;
+    private final Duration window;
+
+    public SlidingWindowRateLimiter(Clock clock, int maxRequests, Duration window) {
+        this.clock = clock;
+        this.maxRequests = maxRequests;
+        this.window = window;
+    }
+
+    /**
+     * Intenta consumir una solicitud para la clave.
+     *
+     * @return {@link Duration#ZERO} si se permite (y queda registrada); si no, el tiempo hasta que se libere
+     *         un hueco en la ventana
+     */
+    public Duration tryAcquire(String key) {
+        Instant now = clock.instant();
+        if (hits.size() > PRUNE_THRESHOLD) {
+            hits.values().removeIf(q -> q.isEmpty() || !q.peekLast().plus(window).isAfter(now));
+        }
+        Duration[] wait = {Duration.ZERO};
+        hits.compute(key, (k, queue) -> {
+            Deque<Instant> q = queue == null ? new ArrayDeque<>() : queue;
+            while (!q.isEmpty() && !q.peekFirst().plus(window).isAfter(now)) {
+                q.pollFirst();
+            }
+            if (q.size() >= maxRequests) {
+                wait[0] = Duration.between(now, q.peekFirst().plus(window));
+            } else {
+                q.addLast(now);
+            }
+            return q;
+        });
+        return wait[0];
+    }
+}
