+package com.itz.inventarios.config;
+
+import jakarta.validation.constraints.Min;
+import java.time.Duration;
+import org.springframework.boot.context.properties.ConfigurationProperties;
+import org.springframework.boot.context.properties.bind.DefaultValue;
+import org.springframework.validation.annotation.Validated;
+
+/**
+ * Propiedades de la recuperación de contraseña (prefijo {@code app.password-reset}).
+ *
+ * @param tokenTtlMinutes         vigencia del token de restablecimiento
+ * @param emailMaxRequests        solicitudes de recuperación permitidas por correo en la ventana
+ * @param ipMaxRequests           solicitudes de recuperación permitidas por IP en la ventana
+ * @param rateLimitWindowMinutes  ventana del límite de frecuencia
+ */
+@Validated
+@ConfigurationProperties(prefix = "app.password-reset")
+public record PasswordResetProperties(
+        @DefaultValue("30") @Min(1) int tokenTtlMinutes,
+        @DefaultValue("3") @Min(1) int emailMaxRequests,
+        @DefaultValue("10") @Min(1) int ipMaxRequests,
+        @DefaultValue("15") @Min(1) int rateLimitWindowMinutes) {
+
+    public Duration tokenTtl() {
