+package com.itz.inventarios.passwordreset.domain;
+
+import jakarta.persistence.Column;
+import jakarta.persistence.Entity;
+import jakarta.persistence.GeneratedValue;
+import jakarta.persistence.GenerationType;
+import jakarta.persistence.Id;
+import jakarta.persistence.Table;
+import java.time.Instant;
+import java.util.UUID;
+import lombok.Getter;
+import lombok.NoArgsConstructor;
+import lombok.Setter;
+
+/** Token de restablecimiento de un solo uso. Solo se guarda el hash SHA-256 del valor enviado por correo. */
+@Entity
+@Table(name = "password_reset_token")
+@Getter
+@Setter
+@NoArgsConstructor
+public class PasswordResetToken {
+
+    @Id
+    @GeneratedValue(strategy = GenerationType.IDENTITY)
+    private Long id;
+
+    @Column(name = "user_id", nullable = false)
+    private UUID userId;
+
+    @Column(name = "token_hash", nullable = false, unique = true, length = 64)
+    private String tokenHash;
+
+    @Column(name = "expires_at", nullable = false)
+    private Instant expiresAt;
+
+    /** Momento en que se usó o se invalidó; {@code null} mientras esté pendiente. */
+    @Column(name = "used_at")
+    private Instant usedAt;
+
+    @Column(name = "created_at", nullable = false, updatable = false)
+    private Instant createdAt;
+
+    public PasswordResetToken(UUID userId, String tokenHash, Instant expiresAt, Instant createdAt) {
+        this.userId = userId;
+        this.tokenHash = tokenHash;
+        this.expiresAt = expiresAt;
+        this.createdAt = createdAt;
+    }
+
+    @Override
+    public String toString() {
+        return "PasswordResetToken[id=" + id + ", userId=" + userId + ", expiresAt=" + expiresAt
+                + ", usedAt=" + usedAt + "]";
+    }
+}
