+package com.itz.inventarios.passwordreset.service;
+
+import com.itz.inventarios.config.MailConfig;
+import java.net.URLEncoder;
+import java.nio.charset.StandardCharsets;
+import org.springframework.mail.SimpleMailMessage;
+import org.springframework.mail.javamail.JavaMailSender;
+import org.springframework.stereotype.Component;
+
+/** Envía el correo con el enlace de restablecimiento. Los fallos de envío se propagan como MailException. */
+@Component
+public class PasswordResetMailer {
+
+    private static final String SUBJECT = "Restablece tu contraseña";
+
+    private final JavaMailSender mailSender;
+    private final MailConfig mailConfig;
+
+    public PasswordResetMailer(JavaMailSender mailSender, MailConfig mailConfig) {
+        this.mailSender = mailSender;
+        this.mailConfig = mailConfig;
+    }
+
+    public void sendResetLink(String to, String token, long validMinutes) {
+        SimpleMailMessage message = new SimpleMailMessage();
+        message.setFrom(mailConfig.from());
+        message.setTo(to);
+        message.setSubject(SUBJECT);
+        message.setText("Recibimos una solicitud para restablecer la contraseña de tu cuenta.\n\n"
+                + "Abre este enlace para definir una nueva contraseña (válido por " + validMinutes
+                + " minutos y de un solo uso):\n" + buildLink(token) + "\n\n"
+                + "Si no fuiste tú, ignora este mensaje: tu contraseña no cambiará.");
+        mailSender.send(message);
+    }
+
+    private String buildLink(String token) {
+        String base = mailConfig.frontendBaseUrl();
+        while (base.endsWith("/")) {
+            base = base.substring(0, base.length() - 1);
+        }
+        return base + "/reset-password?token=" + URLEncoder.encode(token, StandardCharsets.UTF_8);
+    }
+}
