@@ -0,0 +1,113 @@
+package com.itz.inventarios.passwordreset.service;
+
+import com.itz.inventarios.auth.domain.AuthEventType;
+import com.itz.inventarios.auth.service.AuthEventService;
+import com.itz.inventarios.common.exception.TooManyAttemptsException;
+import com.itz.inventarios.common.ratelimit.SlidingWindowRateLimiter;
+import com.itz.inventarios.config.PasswordResetProperties;
+import com.itz.inventarios.passwordreset.domain.PasswordResetToken;
+import com.itz.inventarios.passwordreset.repository.PasswordResetTokenRepository;
+import com.itz.inventarios.user.domain.User;
+import com.itz.inventarios.user.repository.UserRepository;
+import java.security.SecureRandom;
+import java.time.Clock;
+import java.time.Duration;
+import java.time.Instant;
+import java.util.Base64;
+import java.util.List;
+import java.util.Locale;
+import java.util.Optional;
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+import org.springframework.stereotype.Service;
+import org.springframework.transaction.annotation.Transactional;
+
+/**
+ * Solicitud de recuperación de contraseña. El resultado externo es idéntico exista o no la cuenta, esté
+ * habilitada o no y falle o no el envío del correo: solo el límite de frecuencia se distingue (429).
+ */
+@Service
+public class PasswordResetRequestService {
+
+    private static final Logger log = LoggerFactory.getLogger(PasswordResetRequestService.class);
+
+    private static final int TOKEN_BYTES = 32; // 256 bits
+    private static final String UNKNOWN_IP = "unknown";
+
+    private final UserRepository userRepository;
+    private final PasswordResetTokenRepository tokenRepository;
+    private final PasswordResetMailer mailer;
+    private final AuthEventService authEventService;
+    private final PasswordResetProperties properties;
+    private final Clock clock;
+    private final SecureRandom secureRandom = new SecureRandom();
+    private final SlidingWindowRateLimiter emailLimiter;
+    private final SlidingWindowRateLimiter ipLimiter;
+
+    public PasswordResetRequestService(UserRepository userRepository,
+            PasswordResetTokenRepository tokenRepository, PasswordResetMailer mailer,
+            AuthEventService authEventService, PasswordResetProperties properties, Clock clock) {
+        this.userRepository = userRepository;
+        this.tokenRepository = tokenRepository;
+        this.mailer = mailer;
+        this.authEventService = authEventService;
+        this.properties = properties;
+        this.clock = clock;
+        this.emailLimiter = new SlidingWindowRateLimiter(clock, properties.emailMaxRequests(),
+                properties.rateLimitWindow());
+        this.ipLimiter = new SlidingWindowRateLimiter(clock, properties.ipMaxRequests(),
+                properties.rateLimitWindow());
+    }
+
+    /**
+     * @throws TooManyAttemptsException si se supera el límite por correo o por IP
+     */
+    @Transactional
+    public void request(String rawEmail, String ip) {
+        String email = normalize(rawEmail);
+        enforceRateLimit(email, ip);
+        Optional<User> user = userRepository.findByEmail(email).filter(User::isEnabled);
+        authEventService.record(AuthEventType.RESET_REQUEST, user.map(User::getId).orElse(null), email, ip);
+        user.ifPresent(u -> issueAndSend(u, email));
+    }
+
+    private void enforceRateLimit(String email, String ip) {
+        Duration wait = ipLimiter.tryAcquire(ip == null ? UNKNOWN_IP : ip);
+        if (wait.isZero()) {
+            wait = emailLimiter.tryAcquire(email);
+        }
+        if (!wait.isZero()) {
+            throw new TooManyAttemptsException(Math.max(1, (wait.toMillis() + 999) / 1000));
+        }
+    }
+
+    private void issueAndSend(User user, String email) {
+        Instant now = clock.instant();
+        List<PasswordResetToken> previous = tokenRepository
+                .findByUserIdAndUsedAtIsNullAndExpiresAtAfter(user.getId(), now);
+        previous.forEach(t -> t.setUsedAt(now));
+        tokenRepository.saveAll(previous);
+
+        String token = generateToken();
+        tokenRepository.save(new PasswordResetToken(user.getId(), TokenHasher.sha256Hex(token),
+                now.plus(properties.tokenTtl()), now));
+
+        try {
+            mailer.sendResetLink(email, token, properties.tokenTtlMinutes());
+        } catch (RuntimeException e) {
+            // Sin correo ni token en el log; el cliente recibe la misma respuesta genérica.
+            log.error("No se pudo enviar el correo de recuperación (userId={}, causa={})", user.getId(),
+                    e.getClass().getSimpleName());
+        }
+    }
+
+    private String generateToken() {
+        byte[] bytes = new byte[TOKEN_BYTES];
+        secureRandom.nextBytes(bytes);
+        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
+    }
+
+    private static String normalize(String email) {
+        return email == null ? "" : email.trim().toLowerCase(Locale.ROOT);
+    }
+}
