+
+@RestController
+@RequestMapping("/api/v1/auth/password")
+@Tag(name = "Recuperación de contraseña", description = "Solicitud de restablecimiento de contraseña por correo")
+public class PasswordResetController {
+
+    private static final String PROBLEM_JSON = "application/problem+json";
+
+    private final PasswordResetRequestService requestService;
+
+    public PasswordResetController(PasswordResetRequestService requestService) {
+        this.requestService = requestService;
+    }
+
+    @PostMapping("/forgot")
+    @SecurityRequirements
+    @Operation(summary = "Solicitar recuperación de contraseña",
+            description = "Si la cuenta existe y está habilitada, envía un correo con un enlace de un solo uso "
+                    + "(vigente 30 minutos por defecto); un enlace anterior vigente queda invalidado. "
+                    + "La respuesta es siempre la misma, exista o no la cuenta y falle o no el envío.")
+    @ApiResponse(responseCode = "200", description = "Solicitud aceptada (respuesta genérica)",
+            content = @Content(schema = @Schema(implementation = ForgotPasswordResponse.class)))
+    @ApiResponse(responseCode = "400", description = "Correo vacío o con formato inválido",
+            content = @Content(mediaType = PROBLEM_JSON, schema = @Schema(implementation = ProblemDetail.class)))
+    @ApiResponse(responseCode = "429",
+            description = "Demasiadas solicitudes por correo o IP (cabecera Retry-After en segundos)",
+            content = @Content(mediaType = PROBLEM_JSON, schema = @Schema(implementation = ProblemDetail.class)))
+    public ForgotPasswordResponse forgot(@Valid @RequestBody ForgotPasswordRequest request,
+            HttpServletRequest http) {
+        requestService.request(request.email(), http.getRemoteAddr());
+        return ForgotPasswordResponse.generic();
+    }
+}
