+package com.itz.inventarios.common.ratelimit;
+
+import static org.assertj.core.api.Assertions.assertThat;
+
+import com.itz.inventarios.testsupport.MutableClock;
+import java.time.Duration;
+import java.time.Instant;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+
+class SlidingWindowRateLimiterTest {
+
+    private MutableClock clock;
+    private SlidingWindowRateLimiter limiter;
+
+    @BeforeEach
+    void setUp() {
+        clock = new MutableClock(Instant.parse("2026-09-21T10:00:00Z"));
+        limiter = new SlidingWindowRateLimiter(clock, 3, Duration.ofMinutes(15));
+    }
+
+    @Test
+    void permiteHastaElMaximoDentroDeLaVentana() {
+        assertThat(limiter.tryAcquire("a")).isEqualTo(Duration.ZERO);
+        assertThat(limiter.tryAcquire("a")).isEqualTo(Duration.ZERO);
+        assertThat(limiter.tryAcquire("a")).isEqualTo(Duration.ZERO);
+    }
+
+    @Test
+    void alSuperarElMaximoDevuelveLaEsperaHastaQueSeLibereUnHueco() {
+        limiter.tryAcquire("a");
+        clock.advance(Duration.ofMinutes(5));
+        limiter.tryAcquire("a");
+        limiter.tryAcquire("a");
+
+        Duration wait = limiter.tryAcquire("a");
+
+        assertThat(wait).isEqualTo(Duration.ofMinutes(10));
+    }
+
+    @Test
+    void lasSolicitudesRechazadasNoAmplianElBloqueo() {
+        limiter.tryAcquire("a");
+        limiter.tryAcquire("a");
+        limiter.tryAcquire("a");
+        limiter.tryAcquire("a");
+        limiter.tryAcquire("a");
+
+        clock.advance(Duration.ofMinutes(15));
+
+        assertThat(limiter.tryAcquire("a")).isEqualTo(Duration.ZERO);
+    }
+
+    @Test
+    void trasLaVentanaSePuedeSolicitarDeNuevo() {
+        for (int i = 0; i < 3; i++) {
+            limiter.tryAcquire("a");
+        }
+        assertThat(limiter.tryAcquire("a")).isPositive();
+
+        clock.advance(Duration.ofMinutes(15));
+
+        assertThat(limiter.tryAcquire("a")).isEqualTo(Duration.ZERO);
+    }
+
+    @Test
+    void cadaClaveTieneSuPropioContador() {
+        for (int i = 0; i < 3; i++) {
+            limiter.tryAcquire("a");
+        }
+
+        assertThat(limiter.tryAcquire("a")).isPositive();
+        assertThat(limiter.tryAcquire("b")).isEqualTo(Duration.ZERO);
+    }
+}
