+import org.mockito.ArgumentCaptor;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.mock.mockito.MockBean;
+import org.springframework.http.MediaType;
+import org.springframework.mail.MailSendException;
+import org.springframework.mail.SimpleMailMessage;
+import org.springframework.mail.javamail.JavaMailSender;
+import org.springframework.test.context.ActiveProfiles;
+import org.springframework.test.web.servlet.MockMvc;
+import org.springframework.test.web.servlet.request.RequestPostProcessor;
+
+/** Flujo real sobre H2 (Flyway aplica V1 y V2) con el envío de correo simulado. */
+@SpringBootTest
+@AutoConfigureMockMvc
+@ActiveProfiles("test")
+class PasswordResetRequestFlowIntegrationTest {
+
+    private static final String URL = "/api/v1/auth/password/forgot";
+    private static final AtomicInteger IP_SEQ = new AtomicInteger();
+
+    @Autowired
+    private MockMvc mockMvc;
+    @Autowired
+    private UserRepository userRepository;
+    @Autowired
+    private PasswordResetTokenRepository tokenRepository;
+    @Autowired
+    private AuthEventRepository authEventRepository;
+    @MockBean
+    private JavaMailSender mailSender;
+
+    @BeforeEach
+    void resetMail() {
+        reset(mailSender);
+    }
+
+    private static String uniqueIp() {
+        return "10.1." + (IP_SEQ.incrementAndGet() / 250) + "." + (IP_SEQ.get() % 250);
+    }
+
+    private static RequestPostProcessor from(String ip) {
+        return request -> {
+            request.setRemoteAddr(ip);
+            return request;
+        };
+    }
+
+    private User createUser(String email, boolean enabled) {
+        User user = new User();
+        user.setEmail(email);
+        user.setPasswordHash("{unset}");
+        user.setFullName("Usuario de prueba");
+        user.setEnabled(enabled);
+        return userRepository.save(user);
+    }
+
+    private static String uniqueEmail() {
+        return "u-" + UUID.randomUUID() + "@test.local";
+    }
+
+    private String forgot(String email, String ip) throws Exception {
+        return mockMvc.perform(post(URL).with(from(ip)).contentType(MediaType.APPLICATION_JSON)
+                        .content("{\"email\":\"" + email + "\"}"))
+                .andExpect(status().isOk())
+                .andExpect(jsonPath("$.message").exists())
+                .andReturn().getResponse().getContentAsString();
+    }
+
+    private List<AuthEvent> resetEvents(String email) {
+        return authEventRepository.findAll().stream()
+                .filter(e -> e.getTipo() == AuthEventType.RESET_REQUEST && email.equals(e.getEmailIntentado()))
+                .toList();
+    }
+
+    @Test
+    void cuentaExistenteGuardaTokenHasheadoEnviaCorreoYAudita() throws Exception {
+        String email = uniqueEmail();
+        User user = createUser(email, true);
+
+        forgot(email.toUpperCase(), uniqueIp());
+
+        ArgumentCaptor<SimpleMailMessage> message = ArgumentCaptor.forClass(SimpleMailMessage.class);
+        verify(mailSender).send(message.capture());
+        String text = message.getValue().getText();
+        String token = text.substring(text.indexOf("token=") + 6).split("\\s")[0];
+        PasswordResetToken stored = tokenRepository.findByTokenHash(TokenHasher.sha256Hex(token)).orElseThrow();
+        assertThat(stored.getUserId()).isEqualTo(user.getId());
+        assertThat(stored.getTokenHash()).isNotEqualTo(token);
+        assertThat(stored.getUsedAt()).isNull();
+        assertThat(stored.getExpiresAt()).isAfter(stored.getCreatedAt());
+        assertThat(resetEvents(email)).hasSize(1);
+        assertThat(resetEvents(email).get(0).toString()).doesNotContain(token);
+    }
+
+    @Test
+    void laRespuestaEsIdenticaParaCorreoInexistenteYDeshabilitadoYNoSeEnviaCorreo() throws Exception {
+        String existing = uniqueEmail();
+        createUser(existing, true);
+        String disabled = uniqueEmail();
+        createUser(disabled, false);
+
+        String ok = forgot(existing, uniqueIp());
+        reset(mailSender);
+        String missing = forgot(uniqueEmail(), uniqueIp());
+        String off = forgot(disabled, uniqueIp());
+
+        assertThat(missing).isEqualTo(ok);
+        assertThat(off).isEqualTo(ok);
+        verify(mailSender, never()).send(any(SimpleMailMessage.class));
+        assertThat(tokenRepository.findAll().stream()
+                .filter(t -> t.getUserId().equals(userRepository.findByEmail(disabled).orElseThrow().getId())))
+                .isEmpty();
+    }
+
+    @Test
+    void unaNuevaSolicitudInvalidaElTokenAnterior() throws Exception {
+        String email = uniqueEmail();
+        User user = createUser(email, true);
+
+        forgot(email, uniqueIp());
+        forgot(email, uniqueIp());
+
+        List<PasswordResetToken> tokens = tokenRepository.findAll().stream()
+                .filter(t -> t.getUserId().equals(user.getId())).toList();
+        assertThat(tokens).hasSize(2);
+        assertThat(tokens.stream().filter(t -> t.getUsedAt() == null)).hasSize(1);
+    }
+
+    @Test
+    void unFalloDeEnvioNoCambiaLaRespuesta() throws Exception {
+        String email = uniqueEmail();
+        createUser(email, true);
+        String baseline = forgot(uniqueEmail(), uniqueIp());
+        doThrow(new MailSendException("SMTP caído")).when(mailSender).send(any(SimpleMailMessage.class));
+
+        String response = forgot(email, uniqueIp());
+
+        assertThat(response).isEqualTo(baseline);
+        verify(mailSender, times(1)).send(any(SimpleMailMessage.class));
+    }
+
+    @Test
+    void correoInvalidoDa400SinGenerarTokenNiCorreo() throws Exception {
+        mockMvc.perform(post(URL).with(from(uniqueIp())).contentType(MediaType.APPLICATION_JSON)
+                        .content("{\"email\":\"a@b\"}"))
+                .andExpect(status().isBadRequest());
+
+        verify(mailSender, never()).send(any(SimpleMailMessage.class));
+        verify(mailSender, never()).send(any(MimeMessage.class));
+    }
+
+    @Test
+    void alSuperarElLimitePorCorreoResponde429YNoEnviaMasCorreos() throws Exception {
+        String email = uniqueEmail();
+        createUser(email, true);
+        for (int i = 0; i < 3; i++) {
+            forgot(email, uniqueIp());
+        }
+
+        mockMvc.perform(post(URL).with(from(uniqueIp())).contentType(MediaType.APPLICATION_JSON)
+                        .content("{\"email\":\"" + email + "\"}"))
+                .andExpect(status().isTooManyRequests())
+                .andExpect(jsonPath("$.status").value(429));
+
+        verify(mailSender, times(3)).send(any(SimpleMailMessage.class));
+    }
+
+    @Test
+    void alSuperarElLimitePorIpConDistintosCorreosResponde429() throws Exception {
+        String ip = uniqueIp();
+        for (int i = 0; i < 10; i++) {
+            forgot(uniqueEmail(), ip);
+        }
+
+        mockMvc.perform(post(URL).with(from(ip)).contentType(MediaType.APPLICATION_JSON)
+                        .content("{\"email\":\"" + uniqueEmail() + "\"}"))
+                .andExpect(status().isTooManyRequests());
+    }
+}
