+package com.itz.inventarios.passwordreset.service;
+
+import static org.assertj.core.api.Assertions.assertThat;
+import static org.mockito.Mockito.mock;
+import static org.mockito.Mockito.verify;
+
+import com.itz.inventarios.config.MailConfig;
+import org.junit.jupiter.api.Test;
+import org.mockito.ArgumentCaptor;
+import org.springframework.mail.SimpleMailMessage;
+import org.springframework.mail.javamail.JavaMailSender;
+
+class PasswordResetMailerTest {
+
+    private final JavaMailSender mailSender = mock(JavaMailSender.class);
+
+    private SimpleMailMessage send(String baseUrl, String token) {
+        PasswordResetMailer mailer = new PasswordResetMailer(mailSender,
+                new MailConfig("no-reply@inventarios.local", baseUrl));
+        mailer.sendResetLink("usuario@ejemplo.com", token, 30);
+        ArgumentCaptor<SimpleMailMessage> captor = ArgumentCaptor.forClass(SimpleMailMessage.class);
+        verify(mailSender).send(captor.capture());
+        return captor.getValue();
+    }
+
+    @Test
+    void enviaAlDestinatarioDesdeElRemitenteConfigurado() {
+        SimpleMailMessage message = send("https://app.ejemplo.com", "tok-123");
+
+        assertThat(message.getTo()).containsExactly("usuario@ejemplo.com");
+        assertThat(message.getFrom()).isEqualTo("no-reply@inventarios.local");
+        assertThat(message.getSubject()).isNotBlank();
+    }
+
+    @Test
+    void elCuerpoIncluyeElEnlaceConElTokenYLaVigencia() {
+        SimpleMailMessage message = send("https://app.ejemplo.com", "tok-123");
+
+        assertThat(message.getText())
+                .contains("https://app.ejemplo.com/reset-password?token=tok-123")
+                .contains("30 minutos");
+    }
+
+    @Test
+    void laBarraFinalDeLaUrlBaseNoDuplicaSeparadores() {
+        SimpleMailMessage message = send("https://app.ejemplo.com/", "tok-123");
+
+        assertThat(message.getText()).contains("https://app.ejemplo.com/reset-password?token=tok-123")
+                .doesNotContain(".com//reset");
+    }
+
+    @Test
+    void elTokenSeCodificaEnLaUrl() {
+        SimpleMailMessage message = send("https://app.ejemplo.com", "a b&c");
+
+        assertThat(message.getText()).contains("token=a+b%26c");
+    }
+}
