+        service.request("otro@ejemplo.com", "10.0.0.2");
+    }
+
+    @Test
+    void trasLaVentanaSePuedeSolicitarDeNuevo() {
+        when(userRepository.findByEmail("usuario@ejemplo.com")).thenReturn(Optional.of(user(true)));
+        for (int i = 0; i < 3; i++) {
+            service.request("usuario@ejemplo.com", "10.0.0.1");
+        }
+        clock.advance(Duration.ofMinutes(15));
+
+        service.request("usuario@ejemplo.com", "10.0.0.1");
