+
+    @Test
+    void sinIpLaSolicitudSeProcesaYSeAuditaSinIp() {
+        when(userRepository.findByEmail(anyString())).thenReturn(Optional.empty());
+
+        service.request("a@ejemplo.com", null);
+
+        verify(authEventService).record(AuthEventType.RESET_REQUEST, null, "a@ejemplo.com", null);
+    }
+}
