@@ -0,0 +1,119 @@
+package com.itz.inventarios.passwordreset.service;
+
+import com.itz.inventarios.auth.domain.AuthEventType;
+import com.itz.inventarios.auth.service.AuthEventService;
+import com.itz.inventarios.common.exception.ApiException;
+import com.itz.inventarios.passwordreset.domain.PasswordResetToken;
+import com.itz.inventarios.passwordreset.repository.PasswordResetTokenRepository;
+import com.itz.inventarios.user.domain.User;
+import com.itz.inventarios.user.repository.UserRepository;
+import com.itz.inventarios.user.service.PasswordPolicyValidator;
+import java.time.Clock;
+import java.time.Instant;
+import java.util.List;
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+import org.springframework.http.HttpStatus;
+import org.springframework.security.crypto.password.PasswordEncoder;
+import org.springframework.stereotype.Service;
+import org.springframework.transaction.annotation.Transactional;
+
+/**
+ * Restablece la contraseña con un token de un solo uso. El cambio de hash y el consumo del token ocurren en
+ * la misma transacción; si la contraseña no cumple la política o la confirmación no coincide, se rechaza
+ * sin consumir el token. Al cambiar la contraseña se actualiza {@code password_changed_at}, lo que invalida
+ * los JWT emitidos antes.
+ */
+@Service
+public class PasswordResetService {
+
+    public static final String INVALID_TOKEN_MESSAGE =
+            "El enlace de restablecimiento no es válido, ha caducado o ya fue utilizado; solicita uno nuevo.";
+    public static final String MISMATCH_MESSAGE = "La contraseña y su confirmación no coinciden.";
+
+    private static final Logger log = LoggerFactory.getLogger(PasswordResetService.class);
+
+    private final PasswordResetTokenRepository tokenRepository;
+    private final UserRepository userRepository;
+    private final PasswordEncoder passwordEncoder;
+    private final PasswordPolicyValidator policyValidator;
+    private final PasswordResetMailer mailer;
+    private final AuthEventService authEventService;
+    private final Clock clock;
+
+    public PasswordResetService(PasswordResetTokenRepository tokenRepository, UserRepository userRepository,
+            PasswordEncoder passwordEncoder, PasswordPolicyValidator policyValidator, PasswordResetMailer mailer,
+            AuthEventService authEventService, Clock clock) {
+        this.tokenRepository = tokenRepository;
+        this.userRepository = userRepository;
+        this.passwordEncoder = passwordEncoder;
+        this.policyValidator = policyValidator;
+        this.mailer = mailer;
+        this.authEventService = authEventService;
+        this.clock = clock;
+    }
+
+    /**
+     * @throws ApiException 410 si el token no existe, caducó, ya se usó o la cuenta está deshabilitada;
+     *                      422 si la confirmación no coincide o la contraseña incumple la política
+     */
+    @Transactional
+    public void reset(String rawToken, String newPassword, String confirmPassword, String ip) {
+        Instant now = clock.instant();
+        String hash = TokenHasher.sha256Hex(rawToken == null ? "" : rawToken.trim());
+        PasswordResetToken token = tokenRepository.findForUpdateByTokenHash(hash)
+                .filter(t -> t.getUsedAt() == null && t.getExpiresAt().isAfter(now))
+                .orElseThrow(PasswordResetService::invalidToken);
+        User user = userRepository.findById(token.getUserId())
+                .filter(User::isEnabled)
+                .orElseThrow(PasswordResetService::invalidToken);
+
+        validatePassword(newPassword, confirmPassword);
+
+        user.setPasswordHash(passwordEncoder.encode(newPassword));
+        user.setPasswordChangedAt(now);
+        userRepository.save(user);
+
+        token.setUsedAt(now);
+        tokenRepository.save(token);
+        invalidateOtherTokens(user, now);
+
+        authEventService.record(AuthEventType.RESET_DONE, user.getId(), user.getEmail(), ip);
+        notifyChange(user);
+    }
+
+    private void validatePassword(String newPassword, String confirmPassword) {
+        if (newPassword == null || !newPassword.equals(confirmPassword)) {
+            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, MISMATCH_MESSAGE);
+        }
+        List<String> violations = policyValidator.violations(newPassword);
+        if (!violations.isEmpty()) {
+            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
+                    "La contraseña no cumple la política de contraseñas: debe " + String.join(", ", violations) + ".");
+        }
+    }
+
+    private void invalidateOtherTokens(User user, Instant now) {
+        List<PasswordResetToken> pending = tokenRepository
+                .findByUserIdAndUsedAtIsNullAndExpiresAtAfter(user.getId(), now);
+        if (pending.isEmpty()) {
+            return;
+        }
+        pending.forEach(t -> t.setUsedAt(now));
+        tokenRepository.saveAll(pending);
+    }
+
+    private void notifyChange(User user) {
+        try {
+            mailer.sendPasswordChanged(user.getEmail());
+        } catch (RuntimeException e) {
+            // Sin correo ni datos sensibles en el log; el cambio ya es válido
+            log.error("No se pudo enviar el aviso de cambio de contraseña (userId={}, causa={})", user.getId(),
+                    e.getClass().getSimpleName());
+        }
+    }
+
+    private static ApiException invalidToken() {
+        return new ApiException(HttpStatus.GONE, INVALID_TOKEN_MESSAGE);
+    }
+}
