+package com.itz.inventarios.user.service;
+
+import com.itz.inventarios.config.PasswordPolicyProperties;
+import java.util.ArrayList;
+import java.util.List;
+import org.springframework.stereotype.Component;
+
+/** Política de contraseñas centralizada; sus parámetros vienen de {@link PasswordPolicyProperties}. */
+@Component
+public class PasswordPolicyValidator {
+
+    private final PasswordPolicyProperties policy;
+
+    public PasswordPolicyValidator(PasswordPolicyProperties policy) {
+        this.policy = policy;
+    }
+
+    /** @return descripción de cada requisito incumplido; vacía si la contraseña es válida */
+    public List<String> violations(String password) {
+        String value = password == null ? "" : password;
+        List<String> violations = new ArrayList<>();
+        if (value.length() < policy.minLength()) {
+            violations.add("tener al menos " + policy.minLength() + " caracteres");
+        }
+        if (value.length() > policy.maxLength()) {
+            violations.add("no superar " + policy.maxLength() + " caracteres");
+        }
+        if (policy.requireUppercase() && value.chars().noneMatch(Character::isUpperCase)) {
+            violations.add("incluir una letra mayúscula");
+        }
+        if (policy.requireLowercase() && value.chars().noneMatch(Character::isLowerCase)) {
+            violations.add("incluir una letra minúscula");
+        }
+        if (policy.requireDigit() && value.chars().noneMatch(Character::isDigit)) {
+            violations.add("incluir un número");
+        }
+        if (policy.requireSpecial() && value.chars().noneMatch(c -> !Character.isLetterOrDigit(c))) {
+            violations.add("incluir un carácter especial");
+        }
+        return violations;
+    }
+
+    public boolean isValid(String password) {
+        return violations(password).isEmpty();
+    }
+}
