+import org.springframework.boot.test.mock.mockito.MockBean;
+import org.springframework.http.MediaType;
+import org.springframework.mail.SimpleMailMessage;
+import org.springframework.mail.javamail.JavaMailSender;
+import org.springframework.security.crypto.password.PasswordEncoder;
+import org.springframework.test.context.ActiveProfiles;
+import org.springframework.test.web.servlet.MockMvc;
+import org.springframework.test.web.servlet.MvcResult;
+import org.springframework.test.web.servlet.request.RequestPostProcessor;
+
+/** Flujo real sobre H2 (Flyway aplica V1..V3): forgot → reset → login con la nueva contraseña. */
+@SpringBootTest
+@AutoConfigureMockMvc
+@ActiveProfiles("test")
+class PasswordResetFlowIntegrationTest {
+
+    private static final String OLD_PASSWORD = "Clave-Antigua1";
+    private static final String NEW_PASSWORD = "Clave-Nueva-2";
+    private static final AtomicInteger IP_SEQ = new AtomicInteger();
+
+    @Autowired
+    private MockMvc mockMvc;
+    @Autowired
+    private ObjectMapper objectMapper;
+    @Autowired
+    private UserRepository userRepository;
+    @Autowired
+    private PasswordResetTokenRepository tokenRepository;
+    @Autowired
+    private AuthEventRepository authEventRepository;
+    @Autowired
+    private PasswordEncoder passwordEncoder;
+    @MockBean
+    private JavaMailSender mailSender;
+
+    @BeforeEach
+    void resetMail() {
+        Mockito.reset(mailSender);
+    }
+
+    private static String uniqueIp() {
+        return "10.2." + (IP_SEQ.incrementAndGet() / 250) + "." + (IP_SEQ.get() % 250);
+    }
+
+    private static RequestPostProcessor from(String ip) {
+        return request -> {
+            request.setRemoteAddr(ip);
+            return request;
+        };
+    }
+
+    private User createUser(String email) {
+        User user = new User();
+        user.setEmail(email);
+        user.setPasswordHash(passwordEncoder.encode(OLD_PASSWORD));
+        user.setFullName("Usuario de prueba");
+        user.setEnabled(true);
+        return userRepository.save(user);
+    }
+
+    private static String uniqueEmail() {
+        return "u-" + UUID.randomUUID() + "@test.local";
+    }
+
+    private MvcResult login(String email, String password) throws Exception {
+        return mockMvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON)
+                .content("{\"email\":\"" + email + "\",\"password\":\"" + password + "\"}")).andReturn();
+    }
+
+    private String accessToken(String email, String password) throws Exception {
+        MvcResult result = login(email, password);
+        assertThat(result.getResponse().getStatus()).isEqualTo(200);
+        return objectMapper.readTree(result.getResponse().getContentAsString()).get("accessToken").asText();
+    }
+
+    /** Solicita la recuperación y extrae el token en claro del enlace del último correo enviado. */
+    private String requestToken(String email) throws Exception {
+        Mockito.reset(mailSender);
+        mockMvc.perform(post("/api/v1/auth/password/forgot").with(from(uniqueIp()))
+                        .contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"" + email + "\"}"))
+                .andExpect(status().isOk());
+        ArgumentCaptor<SimpleMailMessage> message = ArgumentCaptor.forClass(SimpleMailMessage.class);
+        verify(mailSender).send(message.capture());
+        String text = message.getValue().getText();
+        return text.substring(text.indexOf("token=") + 6).split("\\s")[0];
+    }
+
+    private MvcResult reset(String token, String password, String confirm) throws Exception {
+        return mockMvc.perform(post("/api/v1/auth/password/reset").with(from(uniqueIp()))
+                .contentType(MediaType.APPLICATION_JSON)
+                .content("{\"token\":\"" + token + "\",\"newPassword\":\"" + password
+                        + "\",\"confirmPassword\":\"" + confirm + "\"}")).andReturn();
+    }
+
+    @Test
+    void forgotResetYLoginConLaNuevaContrasena() throws Exception {
+        String email = uniqueEmail();
+        User user = createUser(email);
+        String token = requestToken(email);
+
+        MvcResult result = reset(token, NEW_PASSWORD, NEW_PASSWORD);
+
+        assertThat(result.getResponse().getStatus()).isEqualTo(200);
+        assertThat(login(email, NEW_PASSWORD).getResponse().getStatus()).isEqualTo(200);
+        assertThat(login(email, OLD_PASSWORD).getResponse().getStatus()).isEqualTo(401);
+        PasswordResetToken stored = tokenRepository.findByTokenHash(TokenHasher.sha256Hex(token)).orElseThrow();
+        assertThat(stored.getUsedAt()).isNotNull();
+        assertThat(userRepository.findById(user.getId()).orElseThrow().getPasswordChangedAt()).isNotNull();
+    }
+
+    @Test
+    void elTokenSoloSePuedeUsarUnaVez() throws Exception {
+        String email = uniqueEmail();
+        createUser(email);
+        String token = requestToken(email);
+        reset(token, NEW_PASSWORD, NEW_PASSWORD);
+
+        MvcResult second = reset(token, "Otra-Clave-3x", "Otra-Clave-3x");
+
+        assertThat(second.getResponse().getStatus()).isEqualTo(410);
+        assertThat(login(email, NEW_PASSWORD).getResponse().getStatus()).isEqualTo(200);
+    }
+
+    @Test
+    void tokenCaducadoOInexistenteDa410() throws Exception {
+        String email = uniqueEmail();
+        User user = createUser(email);
+        String token = requestToken(email);
+        PasswordResetToken stored = tokenRepository.findByTokenHash(TokenHasher.sha256Hex(token)).orElseThrow();
+        stored.setExpiresAt(stored.getCreatedAt().minusSeconds(1));
+        tokenRepository.save(stored);
+
+        assertThat(reset(token, NEW_PASSWORD, NEW_PASSWORD).getResponse().getStatus()).isEqualTo(410);
+        assertThat(reset("no-existe", NEW_PASSWORD, NEW_PASSWORD).getResponse().getStatus()).isEqualTo(410);
+        assertThat(login(email, OLD_PASSWORD).getResponse().getStatus()).isEqualTo(200);
+        assertThat(userRepository.findById(user.getId()).orElseThrow().getPasswordChangedAt()).isNull();
+    }
+
+    @Test
+    void politicaIncumplidaYConfirmacionDistintaNoConsumenElToken() throws Exception {
+        String email = uniqueEmail();
+        createUser(email);
+        String token = requestToken(email);
+
+        assertThat(reset(token, "corta", "corta").getResponse().getStatus()).isEqualTo(422);
+        assertThat(reset(token, NEW_PASSWORD, "Distinta-Clave-9").getResponse().getStatus()).isEqualTo(422);
+        assertThat(tokenRepository.findByTokenHash(TokenHasher.sha256Hex(token)).orElseThrow().getUsedAt()).isNull();
+        assertThat(login(email, OLD_PASSWORD).getResponse().getStatus()).isEqualTo(200);
+
+        assertThat(reset(token, NEW_PASSWORD, NEW_PASSWORD).getResponse().getStatus()).isEqualTo(200);
+    }
+
+    @Test
+    void lasSesionesPreviasQuedanInvalidadasYUnaNuevaSesionFunciona() throws Exception {
+        String email = uniqueEmail();
+        createUser(email);
+        String oldSession = accessToken(email, OLD_PASSWORD);
+        mockMvc.perform(get("/api/v1/users/me").header("Authorization", "Bearer " + oldSession))
+                .andExpect(status().isOk());
+        String token = requestToken(email);
+        // El iat del JWT tiene precisión de segundos: se espera a que el cambio caiga en un segundo posterior
+        Thread.sleep(1100);
+
+        reset(token, NEW_PASSWORD, NEW_PASSWORD);
+
+        mockMvc.perform(get("/api/v1/users/me").header("Authorization", "Bearer " + oldSession))
+                .andExpect(status().isUnauthorized());
+        String newSession = accessToken(email, NEW_PASSWORD);
+        mockMvc.perform(get("/api/v1/users/me").header("Authorization", "Bearer " + newSession))
+                .andExpect(status().isOk())
+                .andExpect(jsonPath("$.email").value(email));
+    }
+
+    @Test
+    void enviaCorreoDeNotificacionYAuditaRESET_DONESinSecretos() throws Exception {
+        String email = uniqueEmail();
+        User user = createUser(email);
+        String token = requestToken(email);
+        Mockito.reset(mailSender);
+
+        reset(token, NEW_PASSWORD, NEW_PASSWORD);
+
+        ArgumentCaptor<SimpleMailMessage> message = ArgumentCaptor.forClass(SimpleMailMessage.class);
+        verify(mailSender, times(1)).send(message.capture());
+        assertThat(message.getValue().getTo()).containsExactly(email);
+        assertThat(message.getValue().getText()).doesNotContain(NEW_PASSWORD).doesNotContain(token);
+        List<AuthEvent> done = authEventRepository.findAll().stream()
+                .filter(e -> e.getTipo() == AuthEventType.RESET_DONE && user.getId().equals(e.getUserId()))
+                .toList();
+        assertThat(done).hasSize(1);
+        assertThat(done.get(0).toString()).doesNotContain(NEW_PASSWORD).doesNotContain(token);
+    }
+
+    @Test
+    void unTokenConCuentaDeshabilitadaTrasLaSolicitudSeRechaza() throws Exception {
+        String email = uniqueEmail();
+        User user = createUser(email);
+        String token = requestToken(email);
+        user.setEnabled(false);
+        userRepository.save(user);
+
+        assertThat(reset(token, NEW_PASSWORD, NEW_PASSWORD).getResponse().getStatus()).isEqualTo(410);
+        verify(mailSender, times(1)).send(any(SimpleMailMessage.class));
+    }
+}
