+import { HttpErrorResponse } from '@angular/common/http';
+import { Component, inject } from '@angular/core';
+import {
+  AbstractControl,
+  NonNullableFormBuilder,
+  ReactiveFormsModule,
+  ValidationErrors,
+  Validators,
+} from '@angular/forms';
+import { RouterLink } from '@angular/router';
+import { ButtonModule } from 'primeng/button';
+import { InputTextModule } from 'primeng/inputtext';
+
+import { AuthService } from '../../../core/auth.service';
+
+type ForgotError = 'rateLimited' | 'unavailable';
+
+export const GENERIC_MESSAGE =
+  'Si el correo existe, recibirás instrucciones para restablecer tu contraseña.';
+
+const ERROR_MESSAGES: Record<ForgotError, string> = {
+  rateLimited: 'Demasiadas solicitudes. Espera unos minutos e inténtalo de nuevo.',
+  unavailable: 'El servicio no está disponible en este momento. Inténtalo de nuevo más tarde.',
+};
+
+const FIELD_MESSAGES: Record<string, string> = {
+  required: 'El correo es obligatorio.',
+  email: 'El correo no tiene un formato válido.',
+};
+
+const EMAIL_WITH_DOMAIN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
+
+/** Correo obligatorio y con formato válido (usuario@dominio.tld), ignorando espacios en los extremos. */
+function trimmedEmail(control: AbstractControl): ValidationErrors | null {
+  const value = String(control.value ?? '').trim();
+  if (value === '') {
+    return { required: true };
+  }
+  if (Validators.email({ value } as AbstractControl) || !EMAIL_WITH_DOMAIN.test(value)) {
+    return { email: true };
+  }
+  return null;
+}
+
+/** Solicitud del enlace de recuperación de contraseña. */
+@Component({
+  selector: 'app-forgot-password',
+  standalone: true,
+  imports: [ReactiveFormsModule, RouterLink, InputTextModule, ButtonModule],
+  template: `
+    <section class="mx-auto mt-10 w-full max-w-md rounded-lg bg-white p-6 shadow">
+      <h1 class="mb-2 text-2xl font-semibold text-slate-800">Recuperar contraseña</h1>
+      <p class="mb-6 text-sm text-slate-600">
+        Indica tu correo y te enviaremos un enlace para definir una nueva contraseña.
+      </p>
+
+      @if (sent) {
+        <div
+          data-testid="forgot-success"
+          role="status"
+          class="mb-4 rounded border border-green-300 bg-green-50 p-3 text-sm text-green-800"
+        >
+          {{ genericMessage }}
+        </div>
+      }
+
+      @if (error) {
+        <div
+          data-testid="forgot-error"
+          role="alert"
+          class="mb-4 rounded border border-red-300 bg-red-50 p-3 text-sm text-red-700"
+        >
+          {{ errorMessage }}
+        </div>
+      }
+
+      <form [formGroup]="form" (ngSubmit)="onSubmit()" novalidate class="flex flex-col gap-4">
+        <div class="flex flex-col gap-1">
+          <label for="email" class="text-sm font-medium text-slate-700">Correo</label>
+          <input
+            id="email"
+            type="email"
+            pInputText
+            formControlName="email"
+            autocomplete="username"
+            class="w-full"
+          />
+          @if (fieldError(); as message) {
+            <small class="text-red-600" role="alert">{{ message }}</small>
+          }
+        </div>
+
+        <button pButton type="submit" [disabled]="loading" class="w-full justify-center">
+          Enviar enlace
+        </button>
+      </form>
+
+      <a routerLink="/login" class="mt-4 block text-sm text-blue-700 hover:underline">
+        Volver a iniciar sesión
+      </a>
+    </section>
+  `,
+})
+export class ForgotPasswordComponent {
+  private readonly auth = inject(AuthService);
+
+  readonly form = inject(NonNullableFormBuilder).group({
+    email: ['', [trimmedEmail]],
+  });
+
+  readonly genericMessage = GENERIC_MESSAGE;
+  loading = false;
+  sent = false;
+  error: ForgotError | null = null;
+
+  get errorMessage(): string {
+    return this.error ? ERROR_MESSAGES[this.error] : '';
+  }
+
+  fieldError(): string | null {
+    const control = this.form.controls.email;
+    if (!control.touched || !control.errors) {
+      return null;
+    }
+    return FIELD_MESSAGES[Object.keys(control.errors)[0]] ?? null;
+  }
+
+  onSubmit(): void {
+    if (this.loading) {
+      return;
+    }
+    this.error = null;
+    this.sent = false;
+    if (this.form.invalid) {
+      this.form.markAllAsTouched();
+      return;
+    }
+
+    this.loading = true;
+    this.auth.forgotPassword(this.form.getRawValue().email.trim()).subscribe({
+      next: () => {
+        this.loading = false;
+        this.sent = true;
+      },
+      error: (err: unknown) => {
+        this.loading = false;
+        this.error = err instanceof HttpErrorResponse && err.status === 429 ? 'rateLimited' : 'unavailable';
+      },
+    });
+  }
+}
