+  let navigate: jest.SpyInstance;
+
+  function setup(params: Record<string, string> = { token: 'tok-123' }): void {
+    resetPassword = jest.fn().mockReturnValue(of({ message: 'ok' }));
+    TestBed.configureTestingModule({
+      imports: [ResetPasswordComponent],
+      providers: [
+        provideRouter([]),
+        { provide: AuthService, useValue: { resetPassword } },
+        { provide: ActivatedRoute, useValue: { snapshot: { queryParamMap: convertToParamMap(params) } } },
+      ],
+    });
+    navigate = jest.spyOn(TestBed.inject(Router), 'navigate').mockResolvedValue(true);
+    fixture = TestBed.createComponent(ResetPasswordComponent);
+    fixture.detectChanges();
+    element = fixture.nativeElement as HTMLElement;
+  }
+
+  const input = (id: string) => element.querySelector<HTMLInputElement>(`#${id}`) as HTMLInputElement;
+  const text = () => element.textContent ?? '';
+  const invalidTokenBox = () => element.querySelector('[data-testid="reset-token-invalid"]');
+
+  function submit(password: string, confirm: string): void {
+    input('newPassword').value = password;
+    input('newPassword').dispatchEvent(new Event('input'));
+    input('confirmPassword').value = confirm;
+    input('confirmPassword').dispatchEvent(new Event('input'));
+    fixture.detectChanges();
+    element.querySelector('form')?.dispatchEvent(new Event('submit'));
+    fixture.detectChanges();
+  }
+
+  describe('con token en la URL', () => {
+    beforeEach(() => setup());
+
+    it('enmascara ambos campos de contraseña', () => {
+      expect(input('newPassword').type).toBe('password');
+      expect(input('confirmPassword').type).toBe('password');
+    });
+
+    it('campos vacíos: valida y no llama al servicio', () => {
+      submit('', '');
+
+      expect(text()).toContain('La nueva contraseña es obligatoria');
+      expect(text()).toContain('La confirmación es obligatoria');
+      expect(resetPassword).not.toHaveBeenCalled();
+    });
+
+    it('confirmación distinta: muestra el error y no llama al servicio', () => {
+      submit('Nueva-Clave1', 'Otra-Clave2');
+
+      expect(text()).toContain('no coinciden');
+      expect(resetPassword).not.toHaveBeenCalled();
+      expect(invalidTokenBox()).toBeNull();
+    });
+
+    it('política rechazada (422): muestra el detalle del backend y mantiene el formulario', () => {
