+import { HttpErrorResponse } from '@angular/common/http';
+import { Component, inject } from '@angular/core';
+import {
+  AbstractControl,
+  NonNullableFormBuilder,
+  ReactiveFormsModule,
+  ValidationErrors,
+  Validators,
+} from '@angular/forms';
+import { ActivatedRoute, Router, RouterLink } from '@angular/router';
+import { ButtonModule } from 'primeng/button';
+import { InputTextModule } from 'primeng/inputtext';
+
+import { AuthService } from '../../../core/auth.service';
+
+const FIELD_MESSAGES: Record<'newPassword' | 'confirmPassword', Record<string, string>> = {
+  newPassword: { required: 'La nueva contraseña es obligatoria.' },
+  confirmPassword: { required: 'La confirmación es obligatoria.' },
+};
+
+const MISMATCH_MESSAGE = 'La contraseña y su confirmación no coinciden.';
+const UNAVAILABLE_MESSAGE =
+  'El servicio no está disponible en este momento. Inténtalo de nuevo más tarde.';
+const GENERIC_ERROR_MESSAGE = 'No se pudo restablecer la contraseña. Revisa los datos e inténtalo de nuevo.';
+
+/** La confirmación debe ser idéntica a la nueva contraseña. */
+function passwordsMatch(group: AbstractControl): ValidationErrors | null {
+  const newPassword = group.get('newPassword')?.value as string;
+  const confirmPassword = group.get('confirmPassword')?.value as string;
+  return newPassword === confirmPassword ? null : { mismatch: true };
+}
+
+/** Definición de la nueva contraseña con el token de la query (?token=...). No inicia sesión. */
+@Component({
+  selector: 'app-reset-password',
+  standalone: true,
+  imports: [ReactiveFormsModule, RouterLink, InputTextModule, ButtonModule],
+  template: `
+    <section class="mx-auto mt-10 w-full max-w-md rounded-lg bg-white p-6 shadow">
+      <h1 class="mb-6 text-2xl font-semibold text-slate-800">Restablecer contraseña</h1>
+
+      @if (tokenInvalid) {
+        <div
+          data-testid="reset-token-invalid"
+          role="alert"
+          class="rounded border border-red-300 bg-red-50 p-3 text-sm text-red-700"
+        >
+          El enlace no es válido, ha caducado o ya fue utilizado; solicita uno nuevo.
+        </div>
+        <a routerLink="/forgot-password" class="mt-4 block text-sm text-blue-700 hover:underline">
+          Solicitar un nuevo enlace
+        </a>
+      } @else {
+        @if (errorMessage) {
+          <div
+            data-testid="reset-error"
+            role="alert"
+            class="mb-4 rounded border border-red-300 bg-red-50 p-3 text-sm text-red-700"
+          >
+            {{ errorMessage }}
+          </div>
+        }
+
+        <form [formGroup]="form" (ngSubmit)="onSubmit()" novalidate class="flex flex-col gap-4">
+          <div class="flex flex-col gap-1">
+            <label for="newPassword" class="text-sm font-medium text-slate-700">Nueva contraseña</label>
+            <input
+              id="newPassword"
+              type="password"
+              pInputText
+              formControlName="newPassword"
+              autocomplete="new-password"
+              class="w-full"
+            />
+            @if (fieldError('newPassword'); as message) {
+              <small class="text-red-600" role="alert">{{ message }}</small>
+            }
+          </div>
+
+          <div class="flex flex-col gap-1">
+            <label for="confirmPassword" class="text-sm font-medium text-slate-700">
+              Confirmar contraseña
+            </label>
+            <input
+              id="confirmPassword"
+              type="password"
+              pInputText
+              formControlName="confirmPassword"
+              autocomplete="new-password"
+              class="w-full"
+            />
+            @if (fieldError('confirmPassword'); as message) {
+              <small class="text-red-600" role="alert">{{ message }}</small>
+            }
+          </div>
+
+          <button pButton type="submit" [disabled]="loading" class="w-full justify-center">
+            Restablecer contraseña
+          </button>
+        </form>
+      }
+    </section>
+  `,
+})
+export class ResetPasswordComponent {
+  private readonly auth = inject(AuthService);
+  private readonly router = inject(Router);
+  private readonly token = inject(ActivatedRoute).snapshot.queryParamMap.get('token')?.trim() ?? '';
+
+  readonly form = inject(NonNullableFormBuilder).group(
+    {
+      newPassword: ['', [Validators.required]],
+      confirmPassword: ['', [Validators.required]],
+    },
+    { validators: [passwordsMatch] },
+  );
+
+  loading = false;
+  tokenInvalid = this.token === '';
+  errorMessage = '';
+
+  fieldError(name: 'newPassword' | 'confirmPassword'): string | null {
+    const control = this.form.controls[name];
+    if (!control.touched) {
+      return null;
+    }
+    if (control.errors) {
+      return FIELD_MESSAGES[name][Object.keys(control.errors)[0]] ?? null;
+    }
+    if (name === 'confirmPassword' && this.form.errors?.['mismatch']) {
+      return MISMATCH_MESSAGE;
+    }
+    return null;
+  }
+
+  onSubmit(): void {
+    if (this.loading) {
+      return;
+    }
+    this.errorMessage = '';
+    if (this.form.invalid) {
+      this.form.markAllAsTouched();
+      return;
+    }
