+      next: () => {
+        this.loading = false;
+        void this.router.navigate(['/login'], { queryParams: { reset: 'ok' } });
+      },
+      error: (err: unknown) => {
+        this.loading = false;
+        this.handleError(err);
+      },
+    });
+  }
