+    /** La firma ya está verificada cuando jjwt lanza la expiración, así que los datos son fiables. */
+    private InvalidTokenException expired(ExpiredJwtException e) {
+        try {
+            if (!ALGORITHM.equals(e.getHeader().getAlgorithm())) {
+                return new InvalidTokenException("Algoritmo de firma no permitido", e);
+            }
+            return new ExpiredTokenException("Token expirado", e, toTokenClaims(e.getClaims()));
+        } catch (InvalidTokenException | IllegalArgumentException ex) {
+            return new InvalidTokenException("Token inválido", e);
+        }
+    }
+
+    private static TokenClaims toTokenClaims(Claims claims) {
+        if (claims.getId() == null || claims.getSubject() == null || claims.getExpiration() == null
+                || claims.getIssuedAt() == null) {
+            throw new InvalidTokenException("Token incompleto", null);
+        }
+        List<?> rawRoles = claims.get(CLAIM_ROLES, List.class);
+        List<String> roles = rawRoles == null ? List.of() : rawRoles.stream().map(String::valueOf).toList();
+        return new TokenClaims(claims.getId(), UUID.fromString(claims.getSubject()),
+                claims.get(CLAIM_EMAIL, String.class), roles, claims.getExpiration().toInstant(),
+                claims.getIssuedAt().toInstant());
+    }
 }
