+package com.itz.inventarios.auth.service;
+
+import org.springframework.security.core.AuthenticationException;
+
+/** La sesión asociada al token ya no es utilizable: venció por inactividad o fue cerrada (jti revocado). */
+public class SessionRejectedException extends AuthenticationException {
+
+    public enum Reason {
+        EXPIRED,
+        REVOKED
+    }
+
+    private final Reason reason;
+
+    public SessionRejectedException(Reason reason) {
+        super("Sesión rechazada: " + reason);
+        this.reason = reason;
+    }
+
+    public Reason getReason() {
+        return reason;
+    }
+}
