+package com.itz.inventarios.auth.service;
+
+import com.itz.inventarios.auth.domain.RevokedToken;
+import com.itz.inventarios.auth.repository.RevokedTokenRepository;
+import java.time.Clock;
+import java.time.Instant;
+import java.util.UUID;
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+import org.springframework.dao.DataIntegrityViolationException;
+import org.springframework.scheduling.annotation.Scheduled;
+import org.springframework.stereotype.Service;
+
+/**
+ * Lista de jti revocados. Deliberadamente sin transacción propia: si dos peticiones revocan el mismo jti
+ * a la vez, la violación de la clave primaria se traduce en {@code false} (ya estaba revocado) en lugar
+ * de dejar una transacción marcada para rollback.
+ */
+@Service
+public class TokenRevocationService {
+
+    private static final Logger log = LoggerFactory.getLogger(TokenRevocationService.class);
+
+    private final RevokedTokenRepository repository;
+    private final Clock clock;
+
+    public TokenRevocationService(RevokedTokenRepository repository, Clock clock) {
+        this.repository = repository;
+        this.clock = clock;
+    }
+
+    /**
+     * Revoca el jti de forma idempotente.
+     *
+     * @return {@code true} si esta llamada lo revocó; {@code false} si ya estaba revocado
+     */
+    public boolean revoke(String jti, UUID userId, Instant expiresAt) {
+        if (repository.existsByJti(jti)) {
+            return false;
+        }
+        try {
+            repository.saveAndFlush(new RevokedToken(jti, userId, expiresAt, clock.instant()));
+            return true;
+        } catch (DataIntegrityViolationException e) {
+            return false;
+        }
+    }
+
+    public boolean isRevoked(String jti) {
+        return repository.existsByJti(jti);
+    }
+
+    /** Un token caducado ya no puede usarse, así que su registro de revocación deja de ser necesario. */
+    @Scheduled(initialDelay = 60_000L, fixedDelay = 3_600_000L)
+    public int purgeExpired() {
+        int deleted = repository.deleteByExpiresAtBefore(clock.instant());
+        if (deleted > 0) {
+            log.info("Limpieza de tokens revocados caducados: {} eliminados", deleted);
+        }
+        return deleted;
+    }
+}
