+
+    @Test
+    void refreshFueraDeLaVentanaDeInactividadDa401YAuditaLaExpiracion() throws Exception {
+        User user = createUser();
+        // Token aún vigente (TTL 60 min) pero emitido hace 20 min: supera la ventana de inactividad de 15 min
+        MutableClock pasado = new MutableClock(Instant.now().minus(Duration.ofMinutes(20)));
+        IssuedToken token = new JwtService(new JwtProperties(jwtSecret, 60, 15), pasado).issue(user);
+
+        mockMvc.perform(post("/api/v1/auth/refresh").header("Authorization", bearer(token.token())))
