+import { DOCUMENT } from '@angular/common';
+import { TestBed } from '@angular/core/testing';
+import { NavigationEnd, Router } from '@angular/router';
+import { BehaviorSubject, Subject, of, throwError } from 'rxjs';
+
+import { AuthService } from './auth.service';
+import { IDLE_CONFIG, IdleService } from './idle.service';
+import { SessionChannel, SessionMessage } from './session/session-channel.service';
+
+const IDLE_MS = 60_000;
+const WARNING_MS = 10_000;
+const REFRESH_MS = 20_000;
+
+describe('IdleService', () => {
+  let service: IdleService;
+  let authenticated$: BehaviorSubject<boolean>;
+  let remote$: Subject<SessionMessage>;
+  let routerEvents$: Subject<unknown>;
+  let issuedAt: number | null;
+  let auth: {
+    authenticated$: BehaviorSubject<boolean>;
+    subject: string | null;
+    logout: jest.Mock;
+    refresh: jest.Mock;
+    tokenIssuedAt: jest.Mock;
+    sameSession: jest.Mock;
+  };
+  let post: jest.Mock;
+  let doc: Document;
+
+  function create(): void {
+    service = TestBed.inject(IdleService);
+    service.start();
+  }
+
+  const click = () => doc.dispatchEvent(new Event('click'));
+  const key = () => doc.dispatchEvent(new Event('keydown'));
+  const advance = (ms: number) => jest.advanceTimersByTime(ms);
+
+  beforeEach(() => {
+    jest.useFakeTimers();
+    authenticated$ = new BehaviorSubject<boolean>(true);
+    remote$ = new Subject<SessionMessage>();
+    routerEvents$ = new Subject<unknown>();
+    issuedAt = Date.now();
+    post = jest.fn();
+    auth = {
+      authenticated$,
+      subject: 'u1',
+      logout: jest.fn(),
+      refresh: jest.fn().mockReturnValue(of(undefined)),
+      tokenIssuedAt: jest.fn().mockImplementation(() => issuedAt),
+      sameSession: jest.fn().mockReturnValue(true),
+    };
+    TestBed.configureTestingModule({
+      providers: [
+        { provide: AuthService, useValue: auth },
+        { provide: Router, useValue: { events: routerEvents$.asObservable() } },
+        { provide: SessionChannel, useValue: { messages$: remote$.asObservable(), post } },
+        {
+          provide: IDLE_CONFIG,
+          useValue: { idleTimeoutMs: IDLE_MS, warningMs: WARNING_MS, refreshIntervalMs: REFRESH_MS },
+        },
+      ],
+    });
+    doc = TestBed.inject(DOCUMENT);
+  });
+
+  afterEach(() => {
+    TestBed.resetTestingModule();
+    jest.useRealTimers();
+  });
+
+  describe('expiración por inactividad', () => {
+    it('no cierra la sesión antes del periodo de inactividad (T-10 s)', () => {
+      create();
+      advance(IDLE_MS - 10_000);
+      expect(auth.logout).not.toHaveBeenCalled();
+    });
+
+    it("cierra la sesión con motivo 'inactividad' al vencer", () => {
+      create();
+      advance(IDLE_MS);
+      expect(auth.logout).toHaveBeenCalledTimes(1);
+      expect(auth.logout).toHaveBeenCalledWith('inactividad');
+    });
+
+    it('cierra la sesión una sola vez', () => {
+      create();
+      advance(IDLE_MS * 3);
+      expect(auth.logout).toHaveBeenCalledTimes(1);
+    });
+
+    it('sin sesión no vigila ni cierra nada', () => {
+      authenticated$.next(false);
+      create();
+      click();
+      advance(IDLE_MS * 2);
+      expect(auth.logout).not.toHaveBeenCalled();
+      expect(auth.refresh).not.toHaveBeenCalled();
+    });
+
+    it('empieza a vigilar al iniciar sesión y deja de hacerlo al cerrarla', () => {
+      authenticated$.next(false);
+      create();
+      authenticated$.next(true);
