+    it('al volver a la pestaña con el plazo ya vencido cierra la sesión sin esperar al temporizador', () => {
+      create();
+      jest.setSystemTime(Date.now() + IDLE_MS + 1);
+      doc.dispatchEvent(new Event('visibilitychange'));
+      expect(auth.logout).toHaveBeenCalledWith('inactividad');
+    });
