+    });
+
+    it('otros eventos de router que no son navegación no cuentan', () => {
+      create();
+      advance(IDLE_MS - 10_000);
+      routerEvents$.next({ type: 'otro' });
+      advance(10_000);
+      expect(auth.logout).toHaveBeenCalledTimes(1);
+    });
+
+    it('sin nueva actividad la sesión vence T después de la última', () => {
+      create();
+      advance(30_000);
+      click();
+      advance(IDLE_MS - 1);
+      expect(auth.logout).not.toHaveBeenCalled();
+      advance(1);
+      expect(auth.logout).toHaveBeenCalledTimes(1);
+    });
+  });
+
+  describe('renovación del token (refresh)', () => {
+    it('con actividad y token antiguo renueva el token', () => {
+      issuedAt = Date.now() - REFRESH_MS - 1;
+      create();
+      click();
+      expect(auth.refresh).toHaveBeenCalledTimes(1);
+    });
+
+    it('con actividad y token reciente no renueva', () => {
+      create();
+      click();
+      expect(auth.refresh).not.toHaveBeenCalled();
+    });
+
+    it('sin actividad no renueva aunque pase el tiempo', () => {
+      issuedAt = Date.now() - REFRESH_MS * 10;
+      create();
+      advance(IDLE_MS - 1);
+      expect(auth.refresh).not.toHaveBeenCalled();
+    });
+
+    it('tras renovar no vuelve a hacerlo hasta que pase el intervalo', () => {
+      issuedAt = null;
+      create();
+      click();
+      key();
+      expect(auth.refresh).toHaveBeenCalledTimes(1);
+
+      advance(REFRESH_MS);
+      click();
+      expect(auth.refresh).toHaveBeenCalledTimes(2);
+    });
+
+    it('si el token no se puede leer renueva con la primera actividad', () => {
+      issuedAt = null;
+      create();
+      click();
+      expect(auth.refresh).toHaveBeenCalledTimes(1);
+    });
+
+    it('un fallo de red permite reintentar con la siguiente actividad', () => {
+      issuedAt = null;
+      auth.refresh.mockReturnValueOnce(throwError(() => new Error('red')));
+      create();
+      click();
+      click();
