+
+    it('no lanza renovaciones en paralelo', () => {
+      issuedAt = null;
+      const pending = new Subject<void>();
+      auth.refresh.mockReturnValue(pending);
+      create();
+      click();
+      click();
+      expect(auth.refresh).toHaveBeenCalledTimes(1);
