+    it('la actividad remota no dispara renovación en esta pestaña', () => {
+      issuedAt = Date.now() - REFRESH_MS * 10;
+      create();
+      remote$.next({ type: 'activity', subject: 'u1' });
+      expect(auth.refresh).not.toHaveBeenCalled();
+    });
+  });
+
+  describe('aviso previo y extensión', () => {
+    let seconds: (number | null)[];
+
+    beforeEach(() => {
+      seconds = [];
+    });
+
+    it('muestra el aviso con la cuenta atrás antes de vencer', () => {
+      create();
+      service.warningSecondsLeft$.subscribe((s) => seconds.push(s));
+
+      advance(IDLE_MS - WARNING_MS - 1);
