+      advance(1);
+      expect(seconds[seconds.length - 1]).toBe(10);
+
+      advance(3_000);
+      expect(seconds[seconds.length - 1]).toBe(7);
+    });
+
+    it('la actividad oculta el aviso y reinicia el plazo', () => {
+      create();
+      service.warningSecondsLeft$.subscribe((s) => seconds.push(s));
+      advance(IDLE_MS - 5_000);
+      expect(seconds[seconds.length - 1]).toBe(5);
