+      click();
+      expect(seconds[seconds.length - 1]).toBeNull();
+      advance(IDLE_MS - 1);
+      expect(auth.logout).not.toHaveBeenCalled();
+    });
+
+    it('extend reinicia el plazo y renueva el token', () => {
+      create();
+      service.warningSecondsLeft$.subscribe((s) => seconds.push(s));
+      advance(IDLE_MS - 5_000);
+
+      service.extend();
+
+      expect(auth.refresh).toHaveBeenCalledTimes(1);
+      expect(seconds[seconds.length - 1]).toBeNull();
+      advance(IDLE_MS - 1);
+      expect(auth.logout).not.toHaveBeenCalled();
+    });
+
+    it('al vencer oculta el aviso', () => {
+      create();
+      service.warningSecondsLeft$.subscribe((s) => seconds.push(s));
+      advance(IDLE_MS);
+      expect(seconds[seconds.length - 1]).toBeNull();
