+          { provide: AuthService, useValue: auth },
+          { provide: Router, useValue: { events: routerEvents$.asObservable() } },
+          { provide: SessionChannel, useValue: { messages$: remote$.asObservable(), post } },
+          {
+            provide: IDLE_CONFIG,
+            useValue: { idleTimeoutMs: IDLE_MS, warningMs: 0, refreshIntervalMs: REFRESH_MS },
+          },
+        ],
+      });
+      doc = TestBed.inject(DOCUMENT);
+      create();
+      service.warningSecondsLeft$.subscribe((s) => seconds.push(s));
+      advance(IDLE_MS - 1_000);
+      expect(seconds).toEqual([null]);
+    });
+  });
+
+  describe('sincronización entre pestañas', () => {
+    it('la actividad local se comunica a las demás pestañas', () => {
+      create();
+      click();
+      expect(post).toHaveBeenCalledWith({ type: 'activity', subject: 'u1' });
