+      advance(10_000);
+      click();
+      expect(post).toHaveBeenCalledTimes(2);
+    });
+
+    it('la actividad en otra pestaña reinicia el temporizador de esta', () => {
+      create();
+      advance(IDLE_MS - 10_000);
+      remote$.next({ type: 'activity', subject: 'u1' });
