+++ b/frontend/src/app/core/idle.service.ts
@@ -0,0 +1,231 @@
+import { DOCUMENT } from '@angular/common';
+import { Injectable, InjectionToken, NgZone, OnDestroy, inject } from '@angular/core';
+import { NavigationEnd, Router } from '@angular/router';
+import { BehaviorSubject, Observable, Subscription, filter } from 'rxjs';
+
+import { environment } from '../../environments/environment';
+import { AuthService } from './auth.service';
+import { SessionChannel } from './session/session-channel.service';
+
+/** Tiempos (ms) que gobiernan la inactividad y la renovación del token. */
+export interface IdleConfig {
+  /** Inactividad tras la cual se cierra la sesión. */
+  idleTimeoutMs: number;
+  /** Antelación con la que se avisa del vencimiento (0 = sin aviso). */
+  warningMs: number;
+  /** Antigüedad del token a partir de la cual la actividad lo renueva. */
+  refreshIntervalMs: number;
+}
+
+export const IDLE_CONFIG = new InjectionToken<IdleConfig>('IDLE_CONFIG', {
+  providedIn: 'root',
+  factory: () => ({
+    idleTimeoutMs: environment.idleTimeoutMinutes * 60_000,
+    warningMs: environment.idleWarningSeconds * 1_000,
+    refreshIntervalMs: environment.refreshIntervalMinutes * 60_000,
+  }),
+});
+
+const ACTIVITY_EVENTS = ['click', 'keydown', 'pointerdown', 'touchstart', 'wheel', 'scroll'] as const;
+/** Intervalo mínimo entre avisos de actividad a las demás pestañas. */
+const BROADCAST_THROTTLE_MS = 10_000;
+
+/**
+ * Detecta la actividad del usuario (clics, teclado, navegación y peticiones), renueva el token
+ * mientras hay actividad y cierra la sesión con motivo 'inactividad' al vencer el plazo.
+ * Comparte la actividad con las demás pestañas para que el plazo sea común.
+ */
+@Injectable({ providedIn: 'root' })
+export class IdleService implements OnDestroy {
+  private readonly auth = inject(AuthService);
+  private readonly router = inject(Router);
+  private readonly channel = inject(SessionChannel);
+  private readonly zone = inject(NgZone);
+  private readonly doc = inject(DOCUMENT);
+  private readonly config = inject(IDLE_CONFIG);
+
+  private readonly warningSubject = new BehaviorSubject<number | null>(null);
+  private readonly subscriptions = new Subscription();
+
+  private started = false;
+  private watching = false;
+  private refreshing = false;
+  private deadline = 0;
+  private lastRefreshAt = Number.NEGATIVE_INFINITY;
+  private lastBroadcastAt = Number.NEGATIVE_INFINITY;
+  private warningTimer: ReturnType<typeof setTimeout> | null = null;
+  private expireTimer: ReturnType<typeof setTimeout> | null = null;
+  private countdownTimer: ReturnType<typeof setInterval> | null = null;
+
+  private readonly onActivity = (): void => this.notifyActivity();
+  private readonly onVisibilityChange = (): void => {
+    if (this.watching && this.doc.visibilityState === 'visible' && Date.now() >= this.deadline) {
+      this.expire();
+    }
+  };
+
+  /** Segundos que faltan para expirar mientras se muestra el aviso; null si no hay aviso. */
+  readonly warningSecondsLeft$: Observable<number | null> = this.warningSubject.asObservable();
+
+  /** Empieza a escuchar la actividad y el estado de la sesión. Idempotente. */
+  start(): void {
+    if (this.started) {
+      return;
+    }
+    this.started = true;
+
+    this.zone.runOutsideAngular(() => {
+      ACTIVITY_EVENTS.forEach((name) =>
+        this.doc.addEventListener(name, this.onActivity, { capture: true, passive: true }),
+      );
+      this.doc.addEventListener('visibilitychange', this.onVisibilityChange);
+    });
+
+    this.subscriptions.add(
+      this.auth.authenticated$.subscribe((authenticated) =>
+        authenticated ? this.watch() : this.unwatch(),
+      ),
+    );
+    this.subscriptions.add(
+      this.router.events
+        .pipe(filter((event) => event instanceof NavigationEnd))
+        .subscribe(() => this.notifyActivity()),
+    );
+    this.subscriptions.add(
+      this.channel.messages$.subscribe((message) => {
+        if (message.type === 'activity' && this.watching && this.auth.sameSession(message.subject)) {
+          this.resetTimers();
+        }
+      }),
+    );
+  }
+
+  /** Registra actividad del usuario: reinicia el plazo y renueva el token si ya es antiguo. */
+  notifyActivity(): void {
+    if (!this.watching) {
+      return;
+    }
+    this.resetTimers();
+    this.broadcastActivity();
+    if (Date.now() - this.lastRefresh() >= this.config.refreshIntervalMs) {
+      this.refreshNow();
+    }
+  }
+
+  /** Extiende la sesión desde el aviso previo: reinicia el plazo y renueva el token. */
+  extend(): void {
+    if (!this.watching) {
+      return;
+    }
+    this.resetTimers();
+    this.broadcastActivity();
+    this.refreshNow();
+  }
+
+  ngOnDestroy(): void {
+    ACTIVITY_EVENTS.forEach((name) =>
+      this.doc.removeEventListener(name, this.onActivity, { capture: true }),
+    );
+    this.doc.removeEventListener('visibilitychange', this.onVisibilityChange);
+    this.subscriptions.unsubscribe();
+    this.clearTimers();
+    this.watching = false;
+  }
+
+  private watch(): void {
+    this.watching = true;
+    this.refreshing = false;
+    this.lastRefreshAt = Number.NEGATIVE_INFINITY;
+    this.resetTimers();
+  }
+
+  private unwatch(): void {
+    this.watching = false;
+    this.clearTimers();
+    this.setWarning(null);
+  }
+
+  private lastRefresh(): number {
+    return Math.max(this.auth.tokenIssuedAt() ?? Number.NEGATIVE_INFINITY, this.lastRefreshAt);
+  }
+
+  private refreshNow(): void {
+    if (this.refreshing) {
+      return;
+    }
+    this.refreshing = true;
+    this.zone.run(() =>
+      this.auth.refresh().subscribe({
+        next: () => {
+          this.refreshing = false;
+          this.lastRefreshAt = Date.now();
+        },
+        // Un 401 lo gestiona el interceptor (cierra la sesión); otros fallos se reintentan con la siguiente actividad.
+        error: () => {
+          this.refreshing = false;
+        },
+      }),
+    );
+  }
+
+  private broadcastActivity(): void {
+    const now = Date.now();
+    if (now - this.lastBroadcastAt < BROADCAST_THROTTLE_MS) {
+      return;
+    }
+    this.lastBroadcastAt = now;
+    this.channel.post({ type: 'activity', subject: this.auth.subject });
+  }
+
+  private resetTimers(): void {
+    this.clearTimers();
+    const { idleTimeoutMs, warningMs } = this.config;
+    this.deadline = Date.now() + idleTimeoutMs;
+    this.setWarning(null);
+    this.zone.runOutsideAngular(() => {
+      if (warningMs > 0 && warningMs < idleTimeoutMs) {
+        this.warningTimer = setTimeout(() => this.showWarning(), idleTimeoutMs - warningMs);
+      }
+      this.expireTimer = setTimeout(() => this.expire(), idleTimeoutMs);
+    });
+  }
+
+  private clearTimers(): void {
+    if (this.warningTimer !== null) {
+      clearTimeout(this.warningTimer);
+      this.warningTimer = null;
+    }
+    if (this.expireTimer !== null) {
+      clearTimeout(this.expireTimer);
+      this.expireTimer = null;
+    }
+    if (this.countdownTimer !== null) {
+      clearInterval(this.countdownTimer);
+      this.countdownTimer = null;
+    }
+  }
+
+  private showWarning(): void {
+    this.warningTimer = null;
+    this.updateCountdown();
+    this.zone.runOutsideAngular(() => {
+      this.countdownTimer = setInterval(() => this.updateCountdown(), 1_000);
+    });
+  }
+
+  private updateCountdown(): void {
+    this.setWarning(Math.max(0, Math.ceil((this.deadline - Date.now()) / 1_000)));
+  }
+
+  private expire(): void {
+    this.clearTimers();
+    this.setWarning(null);
+    this.zone.run(() => this.auth.logout('inactividad'));
+  }
+
+  private setWarning(value: number | null): void {
+    if (this.warningSubject.value !== value) {
+      this.zone.run(() => this.warningSubject.next(value));
+    }
+  }
+}
